package com.customweaponsfx;

import lombok.Getter;

/**
 * A numeric comparison ({@code >}, {@code <}, or {@code =} against a threshold) used by amount-based
 * triggers such as {@link Triggers#REGULAR_AMOUNT}. Immutable; matched against each hitsplat's damage.
 */
@Getter
class AmountCondition
{
	/** The comparison operator; its {@link #toString()} is the symbol shown in the UI combo box. */
	enum Op
	{
		GREATER(">"),
		LESS("<"),
		EQUAL("=");

		private final String symbol;

		Op(String symbol)
		{
			this.symbol = symbol;
		}

		@Override
		public String toString()
		{
			return symbol;
		}
	}

	private final Op op;
	private final int value;

	AmountCondition(Op op, int value)
	{
		this.op = op;
		this.value = value;
	}

	/** True if {@code amount} satisfies this comparison. */
	boolean matches(int amount)
	{
		switch (op)
		{
			case GREATER: return amount > value;
			case LESS:    return amount < value;
			case EQUAL:   return amount == value;
			default:      return false;
		}
	}

	/** Serializes to {@code "<OP>:<value>"}, e.g. {@code "EQUAL:73"}. */
	String serialize()
	{
		return op.name() + ":" + value;
	}

	/** Inverse of {@link #serialize()}; returns {@code null} for null/blank/malformed input. */
	static AmountCondition deserialize(String s)
	{
		if (s == null) return null;
		int colon = s.indexOf(':');
		if (colon <= 0) return null;
		try
		{
			Op op = Op.valueOf(s.substring(0, colon).trim());
			int value = Integer.parseInt(s.substring(colon + 1).trim());
			return new AmountCondition(op, value);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import lombok.Getter;

/**
 * Collects the hitsplats of one multi-hit attack (a weapon with an {@link AttackProfile}) across the
 * consecutive ticks they land on, then presents them as a single {@link AttackOutcome} so triggers judge the
 * whole attack at once. Aggregation completes as soon as the profile's expected hit count arrives (so a
 * same-tick pair fires immediately), falling back to the profile's tick span when fewer hits land (e.g. the
 * target died mid-attack).
 *
 * <p>Pure state, mirroring the other trackers: the caller opens it with {@link #begin} on the attack's first
 * hitsplat, feeds each tick's hits with {@link #add}, and once {@link #isComplete} reports it done, reads the
 * combined {@link #buildOutcome} and {@link #reset}s.
 */
class AttackAggregator
{
	private boolean open;
	private int weaponId;
	private int firstTick;
	private int hitCount;
	private int tickSpan;
	private Predicate<List<Boolean>> maxRule;

	@Getter private List<TriggerGroup> groups;
	@Getter private boolean dontOverrideGlobal;

	private final List<Integer> amounts = new ArrayList<>();
	private final List<Boolean> isMaxList = new ArrayList<>();
	private boolean wasSpec;
	private boolean isKill;

	/** True while an attack from {@code weaponId} is being aggregated — its later hits should feed {@link #add}. */
	boolean isActiveFor(int weaponId)
	{
		return open && this.weaponId == weaponId;
	}

	/** Opens aggregation for an attack by {@code weaponId} on {@code tick}, using {@code profile}'s rules. */
	void begin(int weaponId, int tick, AttackProfile profile, List<TriggerGroup> groups, boolean dontOverrideGlobal)
	{
		open = true;
		this.weaponId = weaponId;
		this.firstTick = tick;
		this.hitCount = profile.getHitCount();
		this.tickSpan = profile.getTickSpan();
		this.maxRule = profile.getMaxRule();
		this.groups = groups;
		this.dontOverrideGlobal = dontOverrideGlobal;
		amounts.clear();
		isMaxList.clear();
		wasSpec = false;
		isKill = false;
	}

	/**
	 * Folds one tick's hitsplats into the open attack. {@code wasSpec}/{@code isKill} are OR-ed across the
	 * attack so a special is recognised even if a tail hitsplat lost its spec flag.
	 */
	void add(List<Integer> amounts, List<Boolean> isMaxList, boolean wasSpec, boolean isKill)
	{
		this.amounts.addAll(amounts);
		this.isMaxList.addAll(isMaxList);
		this.wasSpec |= wasSpec;
		this.isKill |= isKill;
	}

	/**
	 * True once every expected hitsplat has arrived, or the attack's whole tick span has elapsed (fallback for
	 * when fewer hits land than expected), so its combined outcome can be fired.
	 */
	boolean isComplete(int currentTick)
	{
		return open && (amounts.size() >= hitCount || currentTick >= firstTick + tickSpan - 1);
	}

	/** The combined outcome of every hitsplat gathered, with max decided by the profile's {@code maxRule}. */
	AttackOutcome buildOutcome()
	{
		boolean allMax  = !isMaxList.isEmpty() && maxRule.test(isMaxList);
		boolean anyHit  = amounts.stream().anyMatch(a -> a > 0);
		boolean allZero = amounts.stream().allMatch(a -> a == 0);
		int[] amountsArr = amounts.stream().mapToInt(Integer::intValue).toArray();
		int maxAmount   = amounts.stream().mapToInt(Integer::intValue).max().orElse(0);
		return new AttackOutcome(wasSpec, anyHit, allZero, allMax, maxAmount, isKill, amountsArr);
	}

	void reset()
	{
		open = false;
		weaponId = 0;
		firstTick = 0;
		hitCount = 0;
		tickSpan = 0;
		maxRule = null;
		groups = null;
		dontOverrideGlobal = false;
		amounts.clear();
		isMaxList.clear();
		wasSpec = false;
		isKill = false;
	}
}

package com.customweaponsfx;

/** Immutable boolean summary of a {@link PendingAttack}'s hitsplats, consumed by trigger evaluation. */
final class AttackOutcome
{
	final boolean wasSpec;
	final boolean anyHit;
	final boolean allZero;
	final boolean allMax;
	final int     maxAmount;
	final boolean isKill;
	/** Each hitsplat's damage this attack; amount-based triggers sum these to compare the total against a threshold. */
	final int[]   amounts;

	AttackOutcome(boolean wasSpec, boolean anyHit, boolean allZero, boolean allMax, int maxAmount, boolean isKill, int[] amounts)
	{
		this.wasSpec   = wasSpec;
		this.anyHit    = anyHit;
		this.allZero   = allZero;
		this.allMax    = allMax;
		this.maxAmount = maxAmount;
		this.isKill    = isKill;
		this.amounts   = amounts;
	}
}

package com.customweaponsfx;

import java.util.List;
import java.util.function.Predicate;
import lombok.Getter;

/**
 * Describes a weapon whose attack lands several hitsplats that may spread across consecutive ticks (e.g.
 * claws' spec, or the dark bow's two arrows), so {@link AttackAggregator} can combine them into a single
 * attack rather than judging each tick's partial. Registered per weapon item id in {@link AttackProfiles}.
 */
@Getter
class AttackProfile
{
	/** Expected number of hitsplats; aggregation completes as soon as this many arrive (fast path). */
	private final int hitCount;

	/** Max consecutive ticks the hitsplats span; a fallback completion if fewer than {@link #hitCount} land. */
	private final int tickSpan;

	/**
	 * When true only special attacks are aggregated (e.g. claws, whose regular attack is a single instant hit);
	 * when false every attack with this weapon is aggregated (e.g. the dark bow, whose regular attack also hits
	 * twice).
	 */
	private final boolean specialOnly;

	/**
	 * Given the per-hitsplat "was max" flags of the whole attack, decides whether it counts as a max hit.
	 * Defined per weapon because these attacks vary: claws paint the max colour on only one splat (so "any"),
	 * whereas the dark bow's two arrows are only a max when both are (so "all").
	 */
	private final Predicate<List<Boolean>> maxRule;

	AttackProfile(int hitCount, int tickSpan, boolean specialOnly, Predicate<List<Boolean>> maxRule)
	{
		this.hitCount = hitCount;
		this.tickSpan = tickSpan;
		this.specialOnly = specialOnly;
		this.maxRule = maxRule;
	}
}

package com.customweaponsfx;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import net.runelite.api.gameval.ItemID;

/**
 * Registry of {@link AttackProfile}s keyed by weapon item id. This is the one place to add a weapon whose
 * attack spreads its hitsplats across ticks; everything else keys off {@link #forWeapon(int)}.
 */
final class AttackProfiles
{
	/** A max hit if any hitsplat shows the max colour — for attacks that only paint it on some splats (claws). */
	private static final Predicate<List<Boolean>> ANY_SPLAT_MAX = flags -> flags.stream().anyMatch(Boolean::booleanValue);
	/** A max hit only if every hitsplat is max — for attacks where all splats max out together (dark bow). */
	private static final Predicate<List<Boolean>> ALL_SPLATS_MAX = flags -> flags.stream().allMatch(Boolean::booleanValue);
	/** A max hit only if the first hitsplat is max — for attacks where only the primary hit can max (twinflame staff). */
	private static final Predicate<List<Boolean>> FIRST_SPLAT_MAX = flags -> !flags.isEmpty() && flags.get(0);
	/** A max hit only if both of the first two hitsplats are max — for dragon claws, whose 3rd/4th splats never max. */
	private static final Predicate<List<Boolean>> FIRST_TWO_SPLATS_MAX = flags -> flags.size() >= 2 && flags.get(0) && flags.get(1);

	private static final Map<Integer, AttackProfile> BY_WEAPON = new HashMap<>();

	static
	{
		// Claws: special only, hitsplats spread over 2 ticks.
		// Dragon claws: 4 hitsplats, 2 per tick over 2 ticks. Only the first two splats can show the max colour
		// (the 3rd/4th never max), so it counts as a max hit only when both of the first two are max.
		register(new AttackProfile(4, 2, true, FIRST_TWO_SPLATS_MAX),
			ItemID.DRAGON_CLAWS, ItemID.BR_DRAGON_CLAWS, ItemID.DRAGON_CLAWS_ORNAMENT,
			ItemID.BH_DRAGON_CLAWS_CORRUPTED, ItemID.DEADMAN_BLIGHTED_DRAGON_CLAWS);
		// Burning claws: 3 hitsplats, 2 on the first tick and 1 on the second, which alone shows the max colour —
		// so any max-coloured splat counts. gameval names item 29577 (in-game "Burning claws") BONE_CLAWS.
		register(new AttackProfile(3, 2, true, ANY_SPLAT_MAX), ItemID.BONE_CLAWS);

		// Dark bow: both the regular and special attack fire two arrows. The pair can share a tick or, at range,
		// land up to a couple of ticks apart, and both can be max — so aggregate every attack (not just the
		// spec) and count it a max hit only when both splats are max. Completion is by hit count (2), so it
		// still fires the moment both arrows land; the generous 5-tick span is only the fallback for when the
		// target dies after one arrow. That stays well inside the dark bow's ≥8-tick attack speed, so a late
		// second arrow is never mistaken for the next attack.
		register(new AttackProfile(2, 5, false, ALL_SPLATS_MAX),
			ItemID.DARKBOW, ItemID.DARKBOW_GREEN, ItemID.DARKBOW_BLUE, ItemID.DARKBOW_YELLOW, ItemID.DARKBOW_WHITE,
			ItemID.BR_DARKBOW, ItemID.BH_DARKBOW_IMBUE, ItemID.DEADMAN_BLIGHTED_DARK_BOW, ItemID.DEADMAN_DARKBOW);

		// Twinflame staff: a Bolt/Blast/Wave cast hits twice, the second hit a tick after the first and only the
		// first able to show the max colour; Strike/Surge cast a single hit. Handled like the dark bow — aggregate
		// every attack up to 2 hits over a 2-tick span with a first-splat-max rule. A double cast completes as soon
		// as its second hit lands; a single cast completes via the tick-span fallback (so it fires ~1 tick later).
		register(new AttackProfile(2, 2, false, FIRST_SPLAT_MAX), ItemID.TWINFLAME_STAFF);
	}

	private AttackProfiles()
	{
	}

	private static void register(AttackProfile profile, int... itemIds)
	{
		for (int itemId : itemIds) BY_WEAPON.put(itemId, profile);
	}

	/** The profile for {@code weaponId}, or {@code null} if the weapon has no multi-hit attack to aggregate. */
	static AttackProfile forWeapon(int weaponId)
	{
		return BY_WEAPON.get(weaponId);
	}
}

package com.customweaponsfx;

/**
 * Tracks which weapon the local player attacked with, so a hitsplat that lands
 * after the swing (ranged/magic projectile travel) is attributed to the weapon
 * actually used — even if the player has since swapped or unequipped it.
 *
 * <p>The weapon is captured at attack-time (the attack animation) rather than at
 * hitsplat-time. It is captured unconditionally, including {@link #NONE} for an
 * unarmed attack, so a stale weapon is never reused after the weapon is unequipped.
 */
class AttackWeaponTracker
{
	static final int NONE = -1;

	private int lastAttackWeaponId = NONE;

	/**
	 * Record the weapon equipped at the moment of an attack animation. Pass
	 * {@link #NONE} (or any negative value) when unarmed, which clears any
	 * previously captured weapon.
	 */
	void onAttack(int equippedWeaponId)
	{
		lastAttackWeaponId = equippedWeaponId;
	}

	/**
	 * Resolve the weapon a landing hitsplat should be attributed to, falling back
	 * to the currently equipped weapon when no attack weapon was captured.
	 */
	int resolveWeaponId(int currentEquippedWeaponId)
	{
		return lastAttackWeaponId >= 0 ? lastAttackWeaponId : currentEquippedWeaponId;
	}

	void reset()
	{
		lastAttackWeaponId = NONE;
	}
}

package com.customweaponsfx;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(CustomWeaponSfxPlugin.CONFIG_GROUP)
public interface CustomWeaponSfxConfig extends Config
{
	String SIDE_PANEL_PRIORITY = "sidePanelPriority";

	@ConfigItem(
		keyName = SIDE_PANEL_PRIORITY,
		name = "Side Panel Priority",
		description = "Panel icon priority, Lower # = higher pos, Higher # = lower pos"
	)
	@Range(min = Integer.MIN_VALUE)
	default int sidePanelPriority() { return 1; }
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Single source of truth for all Custom Weapon SFX config-key construction and (de)serialization.
 * No other class should build a config key string — everything goes through this store.
 *
 * <p>The flat key scheme persisted here:
 * <ul>
 *   <li>{@code specWeaponIds} — comma-joined index of configured weapon item ids.</li>
 *   <li>Per weapon {@code specWeapon_<id>}: {@code _name}, {@code _enabled}, {@code _groupCount},
 *       plus its groups.</li>
 *   <li>A "default" section (e.g. {@code defaultReceived}, {@code globalWeapon}): {@code _groupCount},
 *       {@code _enabled}, plus its groups.</li>
 *   <li>A group {@code <section>_group_<i>}: {@code _name}, {@code _triggers}, {@code _chance},
 *       {@code _soundCount}, and per sound {@code _sound_<j>} / {@code _volume_<j>}.</li>
 * </ul>
 *
 * <p>The store reads/writes through a small {@link Backend} seam so its serialize→deserialize
 * round-trip can be unit-tested against an in-memory map instead of a live {@code ConfigManager}.
 */
@Slf4j
class CustomWeaponSfxConfigStore
{
	/** Minimal key-value seam over {@link ConfigManager}, scoped to {@code CONFIG_GROUP}. */
	interface Backend
	{
		String get(String key);
		void set(String key, Object value);
		void unset(String key);
	}

	private static final String WEAPON_IDS_KEY = "specWeaponIds";
	private static final String EXCLUDED_NPC_IDS_KEY = "excludedNpcIds";
	private static final String EXCLUDED_NPC_NAMES_KEY = "excludedNpcNames";
	private static final String MUTED_WEAPON_SOUND_IDS_KEY = "mutedWeaponSoundIds";
	/**
	 * Legacy global "Don't override Global" key, superseded in 2.11 by a per-weapon flag. Read only, for the
	 * one-time migration in {@link #loadWeapons()}. TODO(2.12): delete once that migration is removed.
	 */
	private static final String LEGACY_DONT_OVERRIDE_GLOBAL_KEY = "dontOverrideGlobal";

	private static final int DEFAULT_CHANCE = 100;
	private static final int DEFAULT_VOLUME = 75;
	private static final int DEFAULT_SOUND_COUNT = 1;

	private final Backend backend;

	CustomWeaponSfxConfigStore(ConfigManager cfg)
	{
		this(new ConfigManagerBackend(cfg));
	}

	CustomWeaponSfxConfigStore(Backend backend)
	{
		this.backend = backend;
	}

	// ----- weapons --------------------------------------------------------------------------

	List<WeaponEntry> loadWeapons()
	{
		List<WeaponEntry> result = new ArrayList<>();
		String idsStr = backend.get(WEAPON_IDS_KEY);
		if (idsStr == null || idsStr.isBlank()) return result;

		for (String idStr : idsStr.split(","))
		{
			Integer itemId = tryParse(idStr);
			if (itemId == null)
			{
				log.debug("Skipping invalid weapon ID in config: {}", idStr);
				continue;
			}

			String section = weaponSection(itemId);
			List<TriggerGroup> groups = loadGroupsOrNull(section);
			if (groups == null)
			{
				// missing or invalid groupCount — drop the weapon entirely (parity with old loader)
				continue;
			}

			String name = backend.get(section + "_name");
			WeaponEntry entry = new WeaponEntry(itemId, name != null ? name : "Weapon #" + itemId, groups);
			String enabledStr = backend.get(section + "_enabled");
			if (enabledStr != null) entry.setEnabled(Boolean.parseBoolean(enabledStr));
			// MIGRATION (added 2.11) — "Don't override Global" was once a single global toggle; weapons
			// saved before it became per-weapon have no key of their own, so they inherit the old global
			// value and we write it straight back as their own key. Once every weapon owns a key the legacy
			// global key is unset below, so this only ever runs once per upgraded install.
			String dogStr = backend.get(section + "_dontOverrideGlobal");
			if (dogStr != null)
			{
				entry.setDontOverrideGlobal(Boolean.parseBoolean(dogStr));
			}
			else
			{
				entry.setDontOverrideGlobal(getBool(LEGACY_DONT_OVERRIDE_GLOBAL_KEY, false));
				backend.set(section + "_dontOverrideGlobal", entry.isDontOverrideGlobal());
			}
			result.add(entry);
		}
		// Every weapon now carries its own key, so the legacy global toggle is fully absorbed.
		// TODO(2.12): once 2.11 has shipped long enough that every active install has loaded once,
		// this migration can be deleted — remove the legacy fallback above, this unset, the
		// LEGACY_DONT_OVERRIDE_GLOBAL_KEY constant, and its unset in resetAll().
		backend.unset(LEGACY_DONT_OVERRIDE_GLOBAL_KEY);
		return result;
	}

	/** Writes name + enabled + dontOverrideGlobal + all groups for one weapon. Does not touch the id index. */
	void saveWeapon(WeaponEntry entry)
	{
		String section = weaponSection(entry.getItemId());
		backend.set(section + "_name", entry.getWeaponName());
		backend.set(section + "_enabled", entry.isEnabled());
		backend.set(section + "_dontOverrideGlobal", entry.isDontOverrideGlobal());
		saveGroups(section, entry.getGroups());
	}

	/** Writes only the group data for a weapon (used by panel edits). */
	void saveWeaponGroups(WeaponEntry entry)
	{
		saveGroups(weaponSection(entry.getItemId()), entry.getGroups());
	}

	void saveWeaponEnabled(int itemId, boolean enabled)
	{
		backend.set(weaponSection(itemId) + "_enabled", enabled);
	}

	void saveWeaponDontOverrideGlobal(int itemId, boolean dontOverrideGlobal)
	{
		backend.set(weaponSection(itemId) + "_dontOverrideGlobal", dontOverrideGlobal);
	}

	/** Unsets every key for one weapon. Caller is responsible for updating the id index. */
	void removeWeapon(WeaponEntry entry)
	{
		String section = weaponSection(entry.getItemId());
		clearGroups(section, entry.getGroups());
		backend.unset(section + "_name");
		backend.unset(section + "_enabled");
		backend.unset(section + "_dontOverrideGlobal");
	}

	void saveWeaponIds(List<WeaponEntry> weapons)
	{
		String ids = weapons.stream()
			.map(e -> String.valueOf(e.getItemId()))
			.collect(Collectors.joining(","));
		backend.set(WEAPON_IDS_KEY, ids);
	}

	// ----- excluded NPC ids -----------------------------------------------------------------

	/** The raw, user-entered comma-separated NPC id string (empty string if unset). */
	String getExcludedNpcIdsRaw()
	{
		String v = backend.get(EXCLUDED_NPC_IDS_KEY);
		return v != null ? v : "";
	}

	void setExcludedNpcIds(String raw)
	{
		backend.set(EXCLUDED_NPC_IDS_KEY, raw == null ? "" : raw);
	}

	/** Parses a comma-separated NPC id string into a set, silently skipping blank/invalid tokens. */
	static Set<Integer> parseNpcIds(String raw)
	{
		Set<Integer> ids = new HashSet<>();
		if (raw == null) return ids;
		for (String token : raw.split(","))
		{
			Integer id = tryParse(token);
			if (id != null) ids.add(id);
		}
		return ids;
	}

	// ----- excluded NPC names ---------------------------------------------------------------

	/** The raw, user-entered comma-separated NPC name string (empty string if unset). */
	String getExcludedNpcNamesRaw()
	{
		String v = backend.get(EXCLUDED_NPC_NAMES_KEY);
		return v != null ? v : "";
	}

	void setExcludedNpcNames(String raw)
	{
		backend.set(EXCLUDED_NPC_NAMES_KEY, raw == null ? "" : raw);
	}

	/**
	 * Parses a comma-separated NPC name string into a set of lowercased, trimmed names for
	 * case-insensitive matching, silently skipping blank tokens.
	 */
	static Set<String> parseNpcNames(String raw)
	{
		Set<String> names = new HashSet<>();
		if (raw == null) return names;
		for (String token : raw.split(","))
		{
			String name = token.trim().toLowerCase();
			if (!name.isEmpty()) names.add(name);
		}
		return names;
	}

	// ----- muted default weapon sounds ------------------------------------------------------

	/** The raw, user-entered comma-separated game sound-effect id string (empty string if unset). */
	String getMutedWeaponSoundIdsRaw()
	{
		String v = backend.get(MUTED_WEAPON_SOUND_IDS_KEY);
		return v != null ? v : "";
	}

	void setMutedWeaponSoundIds(String raw)
	{
		backend.set(MUTED_WEAPON_SOUND_IDS_KEY, raw == null ? "" : raw);
	}

	/** Parses a comma-separated sound-effect id string into a set, silently skipping blank/invalid tokens. */
	static Set<Integer> parseSoundIds(String raw)
	{
		return parseNpcIds(raw);
	}

	// ----- default sections (received / global) ---------------------------------------------

	List<TriggerGroup> loadDefaultGroups(String prefix)
	{
		List<TriggerGroup> groups = loadGroupsOrNull(prefix);
		return groups != null ? groups : new ArrayList<>();
	}

	void saveDefaultGroups(String prefix, List<TriggerGroup> groups)
	{
		saveGroups(prefix, groups);
	}

	void clearDefaultGroups(String prefix, List<TriggerGroup> groups)
	{
		clearGroups(prefix, groups);
	}

	// ----- booleans -------------------------------------------------------------------------

	boolean getBool(String key, boolean def)
	{
		String v = backend.get(key);
		return v == null ? def : Boolean.parseBoolean(v);
	}

	boolean getBool(SfxOption option)
	{
		return getBool(option.configKey(), option.defaultValue());
	}

	void setBool(String key, boolean value)
	{
		backend.set(key, value);
	}

	// ----- reset ----------------------------------------------------------------------------

	/** Wipes all weapons (keys + id index) and both default sections. Booleans are left to the caller. */
	void resetAll(List<WeaponEntry> weapons,
		String receivedPrefix, List<TriggerGroup> receivedGroups,
		String globalPrefix, List<TriggerGroup> globalGroups)
	{
		for (WeaponEntry entry : weapons) removeWeapon(entry);
		backend.unset(WEAPON_IDS_KEY);
		backend.unset(EXCLUDED_NPC_IDS_KEY);
		backend.unset(EXCLUDED_NPC_NAMES_KEY);
		backend.unset(MUTED_WEAPON_SOUND_IDS_KEY);
		backend.unset(LEGACY_DONT_OVERRIDE_GLOBAL_KEY); // TODO(2.12): delete with the load-time migration
		clearDefaultGroups(receivedPrefix, receivedGroups);
		clearDefaultGroups(globalPrefix, globalGroups);
	}

	// ----- internals ------------------------------------------------------------------------

	private static String weaponSection(int itemId)
	{
		return "specWeapon_" + itemId;
	}

	private static String groupKey(String section, int i)
	{
		return section + "_group_" + i;
	}

	/** Returns the section's groups, or {@code null} if its groupCount is missing or unparseable. */
	private List<TriggerGroup> loadGroupsOrNull(String section)
	{
		String countStr = backend.get(section + "_groupCount");
		if (countStr == null || countStr.isBlank()) return null;
		Integer count = tryParse(countStr);
		if (count == null)
		{
			log.debug("Skipping invalid groupCount for {}", section);
			return null;
		}

		List<TriggerGroup> groups = new ArrayList<>();
		for (int i = 0; i < count; i++)
			groups.add(loadGroup(groupKey(section, i), i));
		return groups;
	}

	private TriggerGroup loadGroup(String gk, int index)
	{
		Set<Triggers> triggers = TriggerGroup.deserializeTriggers(backend.get(gk + "_triggers"));
		int chance = parseIntOr(backend.get(gk + "_chance"), DEFAULT_CHANCE);
		int soundCount = parseIntOr(backend.get(gk + "_soundCount"), DEFAULT_SOUND_COUNT);

		List<SoundEntry> sounds = new ArrayList<>();
		for (int j = 0; j < soundCount; j++)
		{
			String sf = backend.get(gk + "_sound_" + j);
			int vol = parseIntOr(backend.get(gk + "_volume_" + j), DEFAULT_VOLUME);
			double weight = parseDoubleOr(backend.get(gk + "_weight_" + j), SoundEntry.DEFAULT_WEIGHT);
			sounds.add(new SoundEntry(sf != null ? sf : "", vol, weight));
		}

		TriggerGroup group = new TriggerGroup(triggers, sounds, chance);
		group.getAmountConditions().putAll(TriggerGroup.deserializeAmountConditions(backend.get(gk + "_amounts")));
		// Pre-name configs (and any with a blank name) fall back to the positional default.
		String name = backend.get(gk + "_name");
		group.setName(name != null && !name.isBlank() ? name : "Sound Group " + (index + 1));
		return group;
	}

	private void saveGroups(String section, List<TriggerGroup> groups)
	{
		backend.set(section + "_groupCount", groups.size());
		for (int i = 0; i < groups.size(); i++)
			saveGroup(groupKey(section, i), groups.get(i));
	}

	private void saveGroup(String gk, TriggerGroup g)
	{
		if (g.getName() != null) backend.set(gk + "_name", g.getName());
		else backend.unset(gk + "_name");
		backend.set(gk + "_triggers", TriggerGroup.serializeTriggers(g.getTriggers()));
		backend.set(gk + "_amounts", TriggerGroup.serializeAmountConditions(g.getAmountConditions()));
		backend.set(gk + "_chance", g.getChance());
		List<SoundEntry> sounds = g.getSounds();
		backend.set(gk + "_soundCount", sounds.size());
		for (int j = 0; j < sounds.size(); j++)
		{
			backend.set(gk + "_sound_" + j, sounds.get(j).getSoundFile());
			backend.set(gk + "_volume_" + j, sounds.get(j).getVolume());
			backend.set(gk + "_weight_" + j, sounds.get(j).getWeight());
		}
	}

	private void clearGroups(String section, List<TriggerGroup> groups)
	{
		backend.unset(section + "_groupCount");
		for (int i = 0; i < groups.size(); i++)
			clearGroup(groupKey(section, i), groups.get(i).getSounds());
	}

	private void clearGroup(String gk, List<SoundEntry> sounds)
	{
		backend.unset(gk + "_name");
		backend.unset(gk + "_triggers");
		backend.unset(gk + "_amounts");
		backend.unset(gk + "_chance");
		backend.unset(gk + "_soundCount");
		for (int j = 0; j < sounds.size(); j++)
		{
			backend.unset(gk + "_sound_" + j);
			backend.unset(gk + "_volume_" + j);
			backend.unset(gk + "_weight_" + j);
		}
	}

	private static Integer tryParse(String s)
	{
		if (s == null) return null;
		try { return Integer.parseInt(s.trim()); }
		catch (NumberFormatException e) { return null; }
	}

	private static int parseIntOr(String s, int def)
	{
		Integer v = tryParse(s);
		return v != null ? v : def;
	}

	private static double parseDoubleOr(String s, double def)
	{
		if (s == null) return def;
		try { return Double.parseDouble(s.trim()); }
		catch (NumberFormatException e) { return def; }
	}

	private static final class ConfigManagerBackend implements Backend
	{
		private final ConfigManager cfg;

		ConfigManagerBackend(ConfigManager cfg) { this.cfg = cfg; }

		@Override
		public String get(String key)
		{
			return cfg.getConfiguration(CustomWeaponSfxPlugin.CONFIG_GROUP, key);
		}

		@Override
		public void set(String key, Object value)
		{
			cfg.setConfiguration(CustomWeaponSfxPlugin.CONFIG_GROUP, key, value);
		}

		@Override
		public void unset(String key)
		{
			cfg.unsetConfiguration(CustomWeaponSfxPlugin.CONFIG_GROUP, key);
		}
	}
}

