package com.customweaponsfx;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Buffers hitsplats and groups them into per-tick attacks. Hitsplats are batched per tick so a
 * multi-hit attack is evaluated together. Grouping by the tick a hit landed on means a skipped
 * {@code onGameTick} — which lets more than one tick's hits accumulate here — still evaluates every
 * tick's attack instead of discarding all but the last. Ticks are returned in ascending order.
 */
class HitAggregator
{
	private final List<DeferredHit> deferredHits = new ArrayList<>();

	void add(DeferredHit hit)
	{
		deferredHits.add(hit);
	}

	boolean isEmpty()
	{
		return deferredHits.isEmpty();
	}

	void clear()
	{
		deferredHits.clear();
	}

	/**
	 * Drains every buffered hit, returning the aggregated attacks grouped by the tick they landed
	 * on, in ascending tick order. Within a tick, hits sharing a key belong to the same attack.
	 */
	List<List<PendingAttack>> drainByTick()
	{
		Map<Integer, Map<Integer, PendingAttack>> attacksByTick = new TreeMap<>();
		for (DeferredHit h : deferredHits)
		{
			Map<Integer, PendingAttack> attacks = attacksByTick.computeIfAbsent(h.tick, k -> new HashMap<>());
			PendingAttack attack = attacks.get(h.key);
			if (attack == null)
			{
				attack = new PendingAttack(h.groups, h.dontOverrideGlobal);
				attack.wasSpec = h.wasSpec;
				attack.tick = h.tick;
				attack.key = h.key;
				attacks.put(h.key, attack);
			}
			attack.amounts.add(h.amount);
			attack.isMaxList.add(h.isMax);
			if (h.actor != null) attack.actors.add(h.actor);
		}
		deferredHits.clear();

		List<List<PendingAttack>> byTick = new ArrayList<>();
		for (Map<Integer, PendingAttack> attacks : attacksByTick.values())
			byTick.add(new ArrayList<>(attacks.values()));
		return byTick;
	}
}

package com.customweaponsfx;

import java.util.Collections;
import java.util.Set;
import net.runelite.api.NPC;

/**
 * Decides which NPC hitsplats are ignored by the plugin.
 *
 * <p>Combines a built-in id blocklist (NPCs whose hitsplats aren't "real" attacks — clones, summoned
 * helpers, multi-bodied bosses, etc.) with user-configured id and name exclusions entered in the panel.
 * The user sets are persisted through {@link CustomWeaponSfxConfigStore} and swapped atomically so the
 * client thread always reads a consistent, immutable set.
 */
class NpcExclusionFilter
{
	/**
	 * NPC IDs whose hitsplats never trigger SFX. Add IDs here to exclude more NPCs — e.g. ones whose
	 * hitsplats aren't "real" attacks (clones, summoned helpers, multi-bodied bosses, etc.).
	 */
	private static final Set<Integer> EXCLUDED_NPC_IDS = Set.of(
		11706,
		11707);

	private final CustomWeaponSfxConfigStore store;

	/** User-configured NPC id exclusions, on top of {@link #EXCLUDED_NPC_IDS}. Swapped atomically. */
	private volatile Set<Integer> userIds = Collections.emptySet();

	/** User-configured NPC name exclusions (lowercased, trimmed) matched against the target's name. */
	private volatile Set<String> userNames = Collections.emptySet();

	NpcExclusionFilter(CustomWeaponSfxConfigStore store)
	{
		this.store = store;
	}

	/** Loads the user id/name exclusions from config. */
	void load()
	{
		userIds = Collections.unmodifiableSet(
			CustomWeaponSfxConfigStore.parseNpcIds(store.getExcludedNpcIdsRaw()));
		userNames = Collections.unmodifiableSet(
			CustomWeaponSfxConfigStore.parseNpcNames(store.getExcludedNpcNamesRaw()));
	}

	boolean isExcluded(NPC npc)
	{
		if (EXCLUDED_NPC_IDS.contains(npc.getId()) || userIds.contains(npc.getId()))
			return true;
		String name = npc.getName();
		return name != null && userNames.contains(name.trim().toLowerCase());
	}

	/** Persists and applies a raw, user-entered comma-separated NPC id string. */
	void setIds(String raw)
	{
		store.setExcludedNpcIds(raw);
		userIds = Collections.unmodifiableSet(CustomWeaponSfxConfigStore.parseNpcIds(raw));
	}

	/** Persists and applies a raw, user-entered comma-separated NPC name string. */
	void setNames(String raw)
	{
		store.setExcludedNpcNames(raw);
		userNames = Collections.unmodifiableSet(CustomWeaponSfxConfigStore.parseNpcNames(raw));
	}

	/** Drops the in-memory user exclusions (config is wiped separately via the store's reset). */
	void clear()
	{
		userIds = Collections.emptySet();
		userNames = Collections.emptySet();
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Actor;

/**
 * The hitsplats from a single attack (same landing tick + key), aggregated so a multi-hit attack is
 * evaluated as one outcome.
 */
class PendingAttack
{
	final List<TriggerGroup> groups;
	final boolean            dontOverrideGlobal;
	final List<Integer>      amounts   = new ArrayList<>();
	final List<Boolean>      isMaxList = new ArrayList<>();
	final List<Actor>        actors    = new ArrayList<>();
	boolean                  wasSpec   = false;
	/** The game tick these hitsplats landed on; used by {@link AttackAggregator} to span a multi-hit attack. */
	int                      tick      = 0;
	/** The aggregation key (weapon item id for outgoing hits); used to look up a weapon's {@link AttackProfile}. */
	int                      key       = 0;

	PendingAttack(List<TriggerGroup> groups)
	{
		this(groups, false);
	}

	PendingAttack(List<TriggerGroup> groups, boolean dontOverrideGlobal)
	{
		this.groups = groups;
		this.dontOverrideGlobal = dontOverrideGlobal;
	}

	/**
	 * Collapses the buffered hitsplats into the boolean outcome used by trigger evaluation. Pure
	 * given {@code isKill}, which the caller derives from {@link #actors} and live client state
	 * (health ratios) so this method stays free of RuneLite {@code Client} dependencies.
	 */
	AttackOutcome collapse(boolean isKill)
	{
		boolean allMax  = isMaxList.stream().allMatch(b -> b);
		boolean anyHit  = amounts.stream().anyMatch(a -> a > 0);
		boolean allZero = amounts.stream().allMatch(a -> a == 0);
		int[] amountsArr = amounts.stream().mapToInt(Integer::intValue).toArray();
		int maxAmount   = amounts.stream().mapToInt(Integer::intValue).max().orElse(0);
		return new AttackOutcome(wasSpec, anyHit, allZero, allMax, maxAmount, isKill, amountsArr);
	}
}

package com.customweaponsfx;

import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import net.runelite.api.Actor;
import net.runelite.api.coords.WorldPoint;

/**
 * Attributes a landing hitsplat to the weapon that <em>launched the projectile</em> which caused it,
 * rather than to whatever weapon the player most recently swung.
 *
 * <p>A magic/ranged projectile lands several ticks after the attack animation. In that window the
 * player can swap weapons and a new attack animation (a manual melee swing, or an auto-retaliate
 * swing) fires — overwriting the single-slot {@link AttackWeaponTracker}. Without projectile
 * tracking the delayed hit would then be mis-attributed to the newly-equipped weapon. This tracker
 * captures the weapon at projectile-spawn time and hands it back when the matching hitsplat lands.
 *
 * <p>Melee (instant) hits and non-projectile "mine" hitsplats (thralls, poison/venom, recoil) have
 * no tracked projectile; the caller falls back to {@link AttackWeaponTracker} for those.
 */
class ProjectileWeaponTracker
{
	/** A projectile fired by the local player, awaiting its landing hitsplat. */
	static final class TrackedProjectile
	{
		final int weaponId;
		final Actor target;          // null for AoE / ground-targeted projectiles
		final WorldPoint targetPoint;
		final int endCycle;          // game cycle the projectile reaches its target (Projectile#getEndCycle)
		final int spawnTick;
		final boolean wasSpec;

		TrackedProjectile(int weaponId, Actor target, WorldPoint targetPoint,
			int endCycle, int spawnTick, boolean wasSpec)
		{
			this.weaponId = weaponId;
			this.target = target;
			this.targetPoint = targetPoint;
			this.endCycle = endCycle;
			this.spawnTick = spawnTick;
			this.wasSpec = wasSpec;
		}
	}

	/**
	 * How far in the future (in game cycles, 30 per tick) a projectile may still be travelling and yet
	 * be considered "arrived" for a hit landing now. A projectile lands on a game tick boundary while
	 * its {@code endCycle} can fall anywhere inside that tick, so the hit-time game cycle may read a
	 * little before {@code endCycle}; one tick of slack absorbs that without matching shots that are
	 * still clearly in flight.
	 */
	private static final int ARRIVE_SLACK_CYCLES = 30;

	private final List<TrackedProjectile> tracked = new CopyOnWriteArrayList<>();
	private final Set<Integer> seenStartCycles = new HashSet<>();

	/**
	 * @return true the first time a given projectile (identified by its start cycle) is seen, so the
	 * per-frame {@code ProjectileMoved} event only records the spawn once.
	 */
	boolean hasSeen(int startCycle)
	{
		return !seenStartCycles.add(startCycle);
	}

	void onProjectileSpawned(int weaponId, Actor target, WorldPoint targetPoint,
		int endCycle, int spawnTick, boolean wasSpec)
	{
		tracked.add(new TrackedProjectile(weaponId, target, targetPoint, endCycle, spawnTick, wasSpec));
	}

	/**
	 * Find the projectile a landing hitsplat should be attributed to, remove it, and return it.
	 * Returns {@code null} when no tracked projectile matches (caller falls back to the instant tracker).
	 *
	 * <p>Matching is keyed on the target and consumes the oldest projectile that has already reached
	 * (or is within a tick of reaching) that target — independent of how long the projectile travelled,
	 * so a long-range shot can't fall outside a tick window and be mis-attributed to a swapped weapon.
	 * A projectile that is still clearly in flight is left untouched, so an instant melee hit landing on
	 * the same target meanwhile correctly falls back to the melee weapon.
	 *
	 * @param nowCycle the current game cycle ({@code client.getGameCycle()}) at hit time
	 */
	TrackedProjectile matchAndRemove(Actor hitActor, int nowCycle)
	{
		// Prefer actor-targeted projectiles aimed at this actor; fall back to AoE projectiles by tile.
		TrackedProjectile best = oldestArrived(hitActor, null, nowCycle);
		if (best == null && hitActor != null)
			best = oldestArrived(null, hitActor.getWorldLocation(), nowCycle);

		if (best != null) tracked.remove(best);
		return best;
	}

	/**
	 * Oldest (FIFO) arrived projectile matching either an actor target or, for AoE, a world tile.
	 * Exactly one of {@code actor} / {@code point} is non-null.
	 */
	private TrackedProjectile oldestArrived(Actor actor, WorldPoint point, int nowCycle)
	{
		TrackedProjectile best = null;
		for (TrackedProjectile tp : tracked)
		{
			if (actor != null)
			{
				if (tp.target != actor) continue;
			}
			else
			{
				if (tp.target != null || tp.targetPoint == null || !tp.targetPoint.equals(point)) continue;
			}
			if (tp.endCycle - nowCycle > ARRIVE_SLACK_CYCLES) continue; // still clearly in flight
			if (best == null || tp.spawnTick < best.spawnTick) best = tp;
		}
		return best;
	}

	/** Drop projectiles that never produced a hitsplat (dodged, blocked, off-screen) so nothing leaks. */
	void prune(int nowTick)
	{
		for (Iterator<TrackedProjectile> it = tracked.iterator(); it.hasNext(); )
		{
			TrackedProjectile tp = it.next();
			if (nowTick - tp.spawnTick > CustomWeaponSfxPlugin.PROJECTILE_TTL_TICKS)
				tracked.remove(tp);
		}
		if (tracked.isEmpty()) seenStartCycles.clear();
	}

	void reset()
	{
		tracked.clear();
		seenStartCycles.clear();
	}
}

