package com.customweaponsfx;

import java.io.File;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.RuneLite;

/**
 * Knows which sounds exist: the .wav resources bundled with the plugin and the user's own .wav files
 * dropped into {@link #SOUNDS_DIR}. Separate from {@link SoundPlayer}, which knows how to play them.
 */
class SoundLibrary
{
	/** Directory under {@code .runelite} where users drop their own .wav files. */
	static final File SOUNDS_DIR = new File(RuneLite.RUNELITE_DIR, "customweaponsfx");

	/** Names of the .wav resources bundled with the plugin (without the .wav extension). */
	static final List<String> BUNDLED_SOUNDS = List.of(
		"bonk", "punch", "shot", "squeak", "oh-baby-a-triple",
		"emotional-damage", "thats-a-lot-of-damage", "okay");

	private final List<String> bundled;
	private List<String> available = new ArrayList<>();

	SoundLibrary()
	{
		SOUNDS_DIR.mkdirs();
		List<String> b = new ArrayList<>(BUNDLED_SOUNDS);
		b.sort(String.CASE_INSENSITIVE_ORDER);
		bundled = Collections.unmodifiableList(b);
		refresh();
	}

	/** Rescans {@link #SOUNDS_DIR} for user .wav files (call after the user adds/removes files). */
	void refresh()
	{
		List<String> sounds = new ArrayList<>();
		File[] files = SOUNDS_DIR.listFiles(f -> f.isFile() && f.getName().toLowerCase().endsWith(".wav"));
		if (files != null)
		{
			for (File f : files)
			{
				String name = f.getName();
				sounds.add(name.substring(0, name.length() - 4));
			}
			sounds.sort(String.CASE_INSENSITIVE_ORDER);
		}
		available = sounds;
	}

	/** User .wav files (without extension), sorted case-insensitively. */
	List<String> getAvailable()
	{
		return available;
	}

	/** Bundled sound names (without extension), sorted case-insensitively. */
	List<String> getBundled()
	{
		return bundled;
	}
}

package com.customweaponsfx;

import java.io.File;
import java.util.List;
import java.util.Set;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

/**
 * Plays the sound effects: resolves which {@link SoundEntry} in a firing {@link TriggerGroup} should
 * play, then plays it off the client thread on a single-threaded executor.
 *
 * <p>Owns the audio executor lifecycle ({@link #start()} / {@link #shutDown()}). Separate from
 * {@link SoundLibrary}, which knows which sounds exist.
 */
@Slf4j
class SoundPlayer
{
	/** Played when a group's sound file is unset/empty. */
	private static final String DEFAULT_BUNDLED_FILE = "squeak.wav";

	private final AudioPlayer audioPlayer;
	private final File soundsDir;
	private ExecutorService executor;

	SoundPlayer(AudioPlayer audioPlayer, File soundsDir)
	{
		this.audioPlayer = audioPlayer;
		this.soundsDir = soundsDir;
	}

	void start()
	{
		executor = Executors.newSingleThreadExecutor();
	}

	void shutDown()
	{
		if (executor != null)
		{
			executor.shutdownNow();
			executor = null;
		}
	}

	/** Fires every group in {@code groups} that the trigger evaluator selects for this attack. */
	void fireMatchingGroups(List<TriggerGroup> groups, boolean wasSpec,
							boolean anyHit, boolean allZero, boolean allMax,
							boolean suppressMax, boolean suppressZero, boolean isKill,
							Set<Triggers> weaponCoveredTriggers, int[] amounts)
	{
		for (TriggerGroup group : TriggerEvaluator.selectFiringGroups(groups, wasSpec, anyHit, allZero,
			allMax, suppressMax, suppressZero, isKill, weaponCoveredTriggers, amounts))
		{
			fireGroup(group);
		}
	}

	/** Rolls the group's chance, picks one of its sounds (weighted), and plays it. */
	void fireGroup(TriggerGroup group)
	{
		int chance = group.getChance();
		if (chance <= 0) return;
		if (chance < 100 && ThreadLocalRandom.current().nextInt(100) >= chance) return;
		List<SoundEntry> sounds = group.getSounds();
		if (sounds.isEmpty()) return;
		// A lone sound always plays; with several, pick one weighted by each sound's chance.
		SoundEntry se = sounds.size() == 1 ? sounds.get(0) : pickWeighted(sounds);
		if (se == null) return;
		playSoundFile(se.getSoundFile(), se.getVolume());
	}

	/**
	 * Picks a sound at random weighted by each entry's {@link SoundEntry#getWeight() weight}.
	 * Returns {@code null} if every weight is 0 (nothing should play).
	 */
	static SoundEntry pickWeighted(List<SoundEntry> sounds)
	{
		double total = 0;
		for (SoundEntry s : sounds) total += Math.max(0, s.getWeight());
		if (total <= 0) return null;

		double roll = ThreadLocalRandom.current().nextDouble(total);
		for (SoundEntry s : sounds)
		{
			roll -= Math.max(0, s.getWeight());
			if (roll < 0) return s;
		}
		return sounds.get(sounds.size() - 1); // unreachable: roll < total guarantees a hit
	}

	void playSoundFile(String soundFile, int volume)
	{
		if (executor == null || executor.isShutdown()) return;
		if (volume == 0) return;
		float gain = TriggerEvaluator.volumeToGain(volume);

		if (soundFile == null || soundFile.isEmpty() || soundFile.startsWith(CustomWeaponSfxPanel.BUNDLED_PREFIX))
		{
			String name = (soundFile == null || soundFile.isEmpty())
				? DEFAULT_BUNDLED_FILE
				: soundFile.substring(CustomWeaponSfxPanel.BUNDLED_PREFIX.length()) + ".wav";
			executor.submit(() ->
			{
				try { audioPlayer.play(CustomWeaponSfxPlugin.class, name, gain); }
				catch (Exception e) { log.debug("Failed to play bundled sound {}", name, e); }
			});
		}
		else
		{
			File f = new File(soundsDir, soundFile + ".wav");
			if (!f.exists())
			{
				log.debug("Sound file missing: {}", f.getAbsolutePath());
				return;
			}
			executor.submit(() ->
			{
				try { audioPlayer.play(f, gain); }
				catch (Exception e) { log.debug("Failed to play {}", soundFile, e); }
			});
		}
	}
}

package com.customweaponsfx;

/**
 * Detects special-attack fires (a drop in spec energy) and remembers, for a short window, which weapon
 * fired the spec so a landing hitsplat can be flagged as a spec hit.
 *
 * <p>The window is keyed on the firing weapon's item id and expires once more than {@link #TIMEOUT_TICKS}
 * ticks elapse so a spec that never produces a hitsplat (missed, out of range) can't taint a later
 * normal attack.
 * Mirrors the other trackers ({@link AttackWeaponTracker}, {@link ProjectileWeaponTracker}): pure
 * state, no game-API or weapon-config knowledge — the caller supplies the spec energy, tick, and the
 * resolved weapon id.
 */
class SpecAttackTracker
{
	/** Drop a pending spec window that never produced a hitsplat once more than this many ticks elapse. */
	private static final int TIMEOUT_TICKS = 10;

	private int lastSpecPct = -1;
	private int pendingItemId = -1;
	private int pendingTick = -1;

	/** Seeds the baseline spec energy so the first drop is detected correctly (call on login). */
	void init(int currentSpec)
	{
		lastSpecPct = currentSpec;
	}

	/**
	 * Advances one game tick: reports whether the spec energy just dropped (a spec was fired) and
	 * expires a stale pending window.
	 *
	 * @return {@code true} if a special attack fired this tick; the caller should then resolve the
	 *         firing weapon and call {@link #arm(int, int)}.
	 */
	boolean onTick(int nowSpec, int nowTick)
	{
		boolean fired = lastSpecPct >= 0 && nowSpec < lastSpecPct;
		lastSpecPct = nowSpec;
		if (pendingItemId >= 0 && nowTick - pendingTick > TIMEOUT_TICKS)
			clearWindow();
		return fired;
	}

	/** Opens the spec window for {@code weaponId} at {@code tick}. */
	void arm(int weaponId, int tick)
	{
		pendingItemId = weaponId;
		pendingTick = tick;
	}

	/** Whether a spec window is currently open (i.e. a landing hit should count as a spec hit). */
	boolean wasSpec()
	{
		return pendingItemId >= 0;
	}

	/** Closes the spec window once its hitsplat has been processed. */
	void clearWindow()
	{
		pendingItemId = -1;
		pendingTick = -1;
	}

	void reset()
	{
		lastSpecPct = -1;
		clearWindow();
	}
}

package com.customweaponsfx;

/**
 * Remembers which weapon a projectile fired on the current game tick was launched with.
 *
 * <p>{@code ProjectileMoved} is dispatched in the render phase, <em>after</em> that tick's
 * {@code GameTick} and after the tick's equipment changes have already been applied — so live
 * equipment (or a snapshot taken during the same {@code GameTick}) already reflects a same-tick
 * weapon swap. But you can't equip a weapon and attack with it on the same tick, so a projectile
 * fired this tick was launched by the weapon held at the <em>start</em> of the tick, i.e. the weapon
 * as of the <em>previous</em> game tick.
 *
 * <p>This holds a one-tick-delayed snapshot: {@link #onGameTick(int)} is called every tick with the
 * currently equipped weapon, and {@link #launchWeapon()} returns the weapon to attribute a projectile
 * fired this tick to.
 */
class TickWeaponSnapshot
{
	static final int NONE = -1;

	private int thisTick = NONE;
	private int prevTick = NONE;

	/** Seed both snapshots when tracking begins (plugin start), so a projectile fired before the first
	 *  game tick is still attributed to the equipped weapon rather than {@link #NONE}. */
	void init(int equippedWeaponId)
	{
		thisTick = prevTick = equippedWeaponId;
	}

	/** Advance the snapshot once per game tick with the currently equipped weapon. */
	void onGameTick(int equippedWeaponId)
	{
		prevTick = thisTick;
		thisTick = equippedWeaponId;
	}

	/**
	 * The weapon a projectile fired on the current tick was launched with — the weapon held at the
	 * start of this tick, unaffected by a swap performed later in the same tick.
	 */
	int launchWeapon()
	{
		return prevTick;
	}

	void reset()
	{
		thisTick = prevTick = NONE;
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.HitsplatID;

/**
 * Pure decision logic for the plugin: given the aggregated outcome of a tick's hitsplats, decide
 * which {@link TriggerGroup}s should fire. Intentionally free of RuneLite {@code Client} state and
 * side effects (no RNG, no audio) so it can be unit tested in isolation.
 */
final class TriggerEvaluator
{
	private TriggerEvaluator()
	{
	}

	/**
	 * Selects, in declaration order, the groups whose triggers match the given attack outcome.
	 *
	 * @param groups                 candidate groups (weapon, global, or received)
	 * @param wasSpec                the attack was a special attack
	 * @param anyHit                 at least one hitsplat dealt damage
	 * @param allZero                every hitsplat was a zero
	 * @param allMax                 every hitsplat was a max hit
	 * @param suppressMax            max-hit triggers should be suppressed (e.g. small max hits)
	 * @param suppressZero           zero triggers should be suppressed (e.g. thrall active)
	 * @param isKill                 the attack killed another player
	 * @param weaponCoveredTriggers  triggers already handled by the weapon; when non-empty, global
	 *                               groups overlapping these are skipped to avoid double-firing
	 * @return the groups that should fire, in order
	 */
	static List<TriggerGroup> selectFiringGroups(
		List<TriggerGroup> groups, boolean wasSpec,
		boolean anyHit, boolean allZero, boolean allMax,
		boolean suppressMax, boolean suppressZero, boolean isKill,
		Set<Triggers> weaponCoveredTriggers)
	{
		return selectFiringGroups(groups, wasSpec, anyHit, allZero, allMax,
			suppressMax, suppressZero, isKill, weaponCoveredTriggers, EMPTY_AMOUNTS);
	}

	private static final int[] EMPTY_AMOUNTS = new int[0];

	/**
	 * As {@link #selectFiringGroups(List, boolean, boolean, boolean, boolean, boolean, boolean, boolean, Set)},
	 * but additionally supplies each hitsplat's {@code amounts} so amount-based triggers (see
	 * {@link Triggers#isAmount()}) can compare against their per-group {@link AmountCondition}.
	 */
	static List<TriggerGroup> selectFiringGroups(
		List<TriggerGroup> groups, boolean wasSpec,
		boolean anyHit, boolean allZero, boolean allMax,
		boolean suppressMax, boolean suppressZero, boolean isKill,
		Set<Triggers> weaponCoveredTriggers, int[] amounts)
	{
		// Pre-filter: when a non-empty suppression set is provided, skip groups whose triggers
		// overlap with triggers the weapon already handles.
		List<TriggerGroup> activeGroups = weaponCoveredTriggers.isEmpty() ? groups : groups.stream()
			.filter(g -> g.getTriggers().isEmpty()
				|| g.getTriggers().stream().noneMatch(weaponCoveredTriggers::contains))
			.collect(Collectors.toList());

		// If a kill occurred and the active groups include KILL-trigger groups, those take exclusive priority.
		boolean hasKillGroups = isKill && activeGroups.stream()
			.anyMatch(g -> !g.getTriggers().isEmpty() && g.getTriggers().contains(Triggers.KILL));

		List<TriggerGroup> firing = new ArrayList<>();
		for (TriggerGroup group : activeGroups)
		{
			Set<Triggers> triggers = group.getTriggers();
			if (triggers.isEmpty()) continue;
			// PLAYER_DEATH groups are fired exclusively from onActorDeath, not from the hitsplat path.
			if (triggers.contains(Triggers.PLAYER_DEATH)) continue;

			boolean groupHasKill = triggers.contains(Triggers.KILL);
			// Kill groups only fire on kills; when kill groups exist, non-kill groups are suppressed.
			if (groupHasKill != hasKillGroups) continue;

			boolean matches;
			if (groupHasKill)
			{
				// isKill is guaranteed true here (hasKillGroups requires it).
				// Any non-KILL triggers in the group also need at least one to match (AND gate).
				boolean hasOtherTriggers = false;
				boolean anyOtherMatches = false;
				for (Triggers trigger : triggers)
				{
					if (trigger == Triggers.KILL) continue;
					hasOtherTriggers = true;
					if (matchesGroupTrigger(group, trigger, wasSpec, anyHit, allZero, allMax, suppressMax, suppressZero, isKill, amounts))
					{
						anyOtherMatches = true;
						break;
					}
				}
				matches = !hasOtherTriggers || anyOtherMatches;
			}
			else
			{
				matches = false;
				for (Triggers trigger : triggers)
				{
					if (matchesGroupTrigger(group, trigger, wasSpec, anyHit, allZero, allMax, suppressMax, suppressZero, isKill, amounts))
					{
						matches = true;
						break;
					}
				}
			}
			if (!matches) continue;
			firing.add(group);
		}
		return firing;
	}

	/**
	 * Dispatches to {@link #matchesAmountTrigger} for amount-based triggers (which need the group's
	 * {@link AmountCondition} and the raw damage), and to {@link #matchesTrigger} for the rest.
	 */
	static boolean matchesGroupTrigger(TriggerGroup group, Triggers trigger, boolean wasSpec,
									   boolean anyHit, boolean allZero, boolean allMax,
									   boolean suppressMax, boolean suppressZero, boolean isKill, int[] amounts)
	{
		if (trigger.isAmount())
		{
			return matchesAmountTrigger(trigger, group.getAmountCondition(trigger), wasSpec, amounts);
		}
		return matchesTrigger(trigger, wasSpec, anyHit, allZero, allMax, suppressMax, suppressZero, isKill);
	}

	/**
	 * True when {@code trigger}'s attack type matches ({@link Triggers#isSpecial()} vs {@code wasSpec})
	 * and the attack's <em>total</em> damage satisfies {@code condition}. All hitsplats from the attack
	 * are summed first, so a multi-hit attack (e.g. a claws special) is compared as one number rather
	 * than per hitsplat. A null condition, or an attack with no hitsplats, never matches.
	 */
	static boolean matchesAmountTrigger(Triggers trigger, AmountCondition condition, boolean wasSpec, int[] amounts)
	{
		if (condition == null || amounts == null || amounts.length == 0) return false;
		if (trigger.isSpecial() != wasSpec) return false;
		int total = 0;
		for (int amount : amounts)
		{
			total += amount;
		}
		return condition.matches(total);
	}

	static boolean matchesTrigger(Triggers trigger, boolean wasSpec,
								  boolean anyHit, boolean allZero, boolean allMax,
								  boolean suppressMax, boolean suppressZero, boolean isKill)
	{
		switch (trigger)
		{
			case REGULAR_ZERO: return !wasSpec && allZero && !suppressZero;
			case REGULAR_HIT:  return !wasSpec && anyHit && !allMax;
			case REGULAR_MAX:  return !wasSpec && allMax && !suppressMax;
			case SPECIAL_ZERO: return wasSpec && allZero;
			case SPECIAL_HIT:  return wasSpec && anyHit && !allMax;
			case SPECIAL_MAX:  return wasSpec && allMax && !suppressMax;
			case ALL:          return true;
			case KILL:         return isKill;
			default:           return false;
		}
	}

	static boolean isMaxHit(int hitsplatType)
	{
		return hitsplatType == HitsplatID.DAMAGE_MAX_ME
			|| hitsplatType == HitsplatID.DAMAGE_MAX_ME_CYAN
			|| hitsplatType == HitsplatID.DAMAGE_MAX_ME_ORANGE
			|| hitsplatType == HitsplatID.DAMAGE_MAX_ME_YELLOW
			|| hitsplatType == HitsplatID.DAMAGE_MAX_ME_WHITE
			|| hitsplatType == HitsplatID.DAMAGE_MAX_ME_POISE;
	}

	static float volumeToGain(int volume)
	{
		if (volume <= 0) return -80f;
		return 20.0f * (float) Math.log10(volume / 100.0f);
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import lombok.Getter;
import lombok.Setter;

@Getter
public class TriggerGroup
{
	private final Set<Triggers> triggers;
	private final List<SoundEntry> sounds;
	/** Per-trigger numeric comparisons for amount-based triggers (see {@link Triggers#isAmount()}). */
	private final Map<Triggers, AmountCondition> amountConditions = new EnumMap<>(Triggers.class);
	@Setter private int chance;
	@Setter private String name;

	public TriggerGroup(Set<Triggers> triggers, List<SoundEntry> sounds, int chance)
	{
		this.triggers = triggers != null ? triggers : EnumSet.noneOf(Triggers.class);
		this.sounds = sounds != null ? sounds : new ArrayList<>();
		this.chance = chance;
	}

	/** The {@link AmountCondition} configured for {@code trigger}, or {@code null} if none. */
	public AmountCondition getAmountCondition(Triggers trigger)
	{
		return amountConditions.get(trigger);
	}

	/** Sets (or, when {@code condition} is null, clears) the comparison for an amount-based trigger. */
	public void setAmountCondition(Triggers trigger, AmountCondition condition)
	{
		if (condition == null) amountConditions.remove(trigger);
		else amountConditions.put(trigger, condition);
	}

	/**
	 * True if {@code name} (case-insensitively) already belongs to a group in {@code groups},
	 * skipping {@code exclude} (pass the group being renamed so it doesn't clash with itself).
	 */
	public static boolean isNameTaken(List<TriggerGroup> groups, String name, TriggerGroup exclude)
	{
		if (name == null) return false;
		for (TriggerGroup g : groups)
		{
			if (g == exclude) continue;
			if (name.equalsIgnoreCase(g.getName())) return true;
		}
		return false;
	}

	/** Lowest unused {@code "Sound Group N"} name for a fresh group in {@code groups}. */
	public static String defaultName(List<TriggerGroup> groups)
	{
		int n = 1;
		while (isNameTaken(groups, "Sound Group " + n, null)) n++;
		return "Sound Group " + n;
	}

	public static String serializeTriggers(Set<Triggers> triggers)
	{
		if (triggers == null || triggers.isEmpty()) return "";
		StringBuilder sb = new StringBuilder();
		for (Triggers t : triggers)
		{
			if (sb.length() > 0) sb.append(',');
			sb.append(t.name());
		}
		return sb.toString();
	}

	public static Set<Triggers> deserializeTriggers(String s)
	{
		Set<Triggers> set = EnumSet.noneOf(Triggers.class);
		if (s == null || s.isBlank()) return set;
		for (String part : s.split(","))
		{
			part = part.trim();
			if (part.isEmpty()) continue;
			try { set.add(Triggers.valueOf(part)); }
			catch (IllegalArgumentException ignored) {}
		}
		return set;
	}

	/**
	 * Serializes amount-trigger conditions to {@code "TRIGGER=OP:value;TRIGGER=OP:value"}, e.g.
	 * {@code "REGULAR_AMOUNT=EQUAL:73"}. Empty when no conditions are set.
	 */
	public static String serializeAmountConditions(Map<Triggers, AmountCondition> conditions)
	{
		if (conditions == null || conditions.isEmpty()) return "";
		StringBuilder sb = new StringBuilder();
		for (Map.Entry<Triggers, AmountCondition> e : conditions.entrySet())
		{
			if (e.getValue() == null) continue;
			if (sb.length() > 0) sb.append(';');
			sb.append(e.getKey().name()).append('=').append(e.getValue().serialize());
		}
		return sb.toString();
	}

	public static Map<Triggers, AmountCondition> deserializeAmountConditions(String s)
	{
		Map<Triggers, AmountCondition> map = new EnumMap<>(Triggers.class);
		if (s == null || s.isBlank()) return map;
		for (String part : s.split(";"))
		{
			part = part.trim();
			if (part.isEmpty()) continue;
			int eq = part.indexOf('=');
			if (eq <= 0) continue;
			try
			{
				Triggers trigger = Triggers.valueOf(part.substring(0, eq).trim());
				AmountCondition condition = AmountCondition.deserialize(part.substring(eq + 1));
				if (condition != null) map.put(trigger, condition);
			}
			catch (IllegalArgumentException ignored) {}
		}
		return map;
	}
}

package com.customweaponsfx;

import lombok.Getter;

@Getter
public enum Triggers
{
	REGULAR_ZERO("Regular attack zero"),
	REGULAR_HIT("Regular attack hit"),
	REGULAR_MAX("Regular attack max"),
	REGULAR_AMOUNT("Regular attack amount", false, true),
	SPECIAL_ZERO("Special attack zero"),
	SPECIAL_HIT("Special attack hit"),
	SPECIAL_MAX("Special attack max"),
	SPECIAL_AMOUNT("Special attack amount", true, true),
	ALL("All attacks"),
	KILL("Player kill"),
	PLAYER_DEATH("Player death");

	private final String name;
	/** True for triggers that only fire on a special attack (used to gate amount triggers by attack type). */
	private final boolean special;
	/** True for triggers that carry a per-group {@link AmountCondition} comparing against the hit damage. */
	private final boolean amount;

	Triggers(String name)
	{
		this(name, false, false);
	}

	Triggers(String name, boolean special, boolean amount)
	{
		this.name = name;
		this.special = special;
		this.amount = amount;
	}

	@Override
	public String toString()
	{
		return name;
	}
}

package com.customweaponsfx;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.awt.event.KeyEvent;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.function.Consumer;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.ItemComposition;
import net.runelite.api.widgets.ItemQuantityMode;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.game.chatbox.ChatboxTextInput;
import net.runelite.client.ui.JagexColors;

@Singleton
public class WeaponChatboxSearch extends ChatboxTextInput
{
	private static final int ICON_HEIGHT = 32;
	private static final int ICON_WIDTH = 36;
	private static final int PADDING = 6;
	private static final int MAX_RESULTS = 24;
	private static final int FONT_SIZE = 16;
	private static final int HOVERED_OPACITY = 128;
	private static final int WEAPON_SLOT = EquipmentInventorySlot.WEAPON.getSlotIdx();

	private final ChatboxPanelManager chatboxPanelManager;
	private final ItemManager itemManager;
	private final Client client;

	private final Map<Integer, ItemComposition> results = new LinkedHashMap<>();
	private int index = -1;
	private Consumer<Integer> onItemSelected;

	@Inject
	WeaponChatboxSearch(ChatboxPanelManager chatboxPanelManager, ClientThread clientThread,
		ItemManager itemManager, Client client)
	{
		super(chatboxPanelManager, clientThread);
		this.chatboxPanelManager = chatboxPanelManager;
		this.itemManager = itemManager;
		this.client = client;

		lines(1);
		prompt("Search for a weapon");
		onChanged(searchString ->
			clientThread.invokeLater(() ->
			{
				filterResults();
				update();
			}));
	}

	@Override
	protected void update()
	{
		Widget container = chatboxPanelManager.getContainerWidget();
		container.deleteAllChildren();

		Widget promptWidget = container.createChild(-1, WidgetType.TEXT);
		promptWidget.setText(getPrompt());
		promptWidget.setTextColor(0x800000);
		promptWidget.setFontId(getFontID());
		promptWidget.setOriginalX(0);
		promptWidget.setOriginalY(5);
		promptWidget.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
		promptWidget.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		promptWidget.setOriginalHeight(FONT_SIZE);
		promptWidget.setXTextAlignment(WidgetTextAlignment.CENTER);
		promptWidget.setYTextAlignment(WidgetTextAlignment.CENTER);
		promptWidget.setWidthMode(WidgetSizeMode.MINUS);
		promptWidget.revalidate();

		Widget cancelBtn = container.createChild(-1, WidgetType.TEXT);
		cancelBtn.setText("Cancel");
		cancelBtn.setTextColor(0xAA0000);
		cancelBtn.setFontId(getFontID());
		cancelBtn.setOriginalX(container.getWidth() - 56);
		cancelBtn.setOriginalY(5);
		cancelBtn.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
		cancelBtn.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		cancelBtn.setOriginalHeight(FONT_SIZE);
		cancelBtn.setOriginalWidth(56);
		cancelBtn.setHasListener(true);
		cancelBtn.setAction(0, "Close");
		cancelBtn.setOnOpListener((JavaScriptCallback) ev -> chatboxPanelManager.close());
		cancelBtn.revalidate();

		buildEdit(0, 5 + FONT_SIZE, container.getWidth(), FONT_SIZE);

		Widget separator = container.createChild(-1, WidgetType.LINE);
		separator.setOriginalX(0);
		separator.setOriginalY(8 + (FONT_SIZE * 2));
		separator.setXPositionMode(WidgetPositionMode.ABSOLUTE_CENTER);
		separator.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
		separator.setOriginalHeight(0);
		separator.setOriginalWidth(16);
		separator.setWidthMode(WidgetSizeMode.MINUS);
		separator.setTextColor(0x666666);
		separator.revalidate();

		int x = PADDING;
		int y = PADDING * 3;
		int idx = 0;
		for (ItemComposition itemComposition : results.values())
		{
			Widget item = container.createChild(-1, WidgetType.GRAPHIC);
			item.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
			item.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
			item.setOriginalX(x);
			item.setOriginalY(y + FONT_SIZE * 2);
			item.setOriginalHeight(ICON_HEIGHT);
			item.setOriginalWidth(ICON_WIDTH);
			item.setName(JagexColors.MENU_TARGET_TAG + itemComposition.getName());
			item.setItemId(itemComposition.getId());
			item.setItemQuantity(10000);
			item.setItemQuantityMode(ItemQuantityMode.NEVER);
			item.setBorderType(1);
			item.setAction(0, "Add weapon (" + itemComposition.getId() + ")");
			item.setHasListener(true);

			if (index == idx)
			{
				item.setOpacity(HOVERED_OPACITY);
			}
			else
			{
				item.setOnMouseOverListener((JavaScriptCallback) ev -> item.setOpacity(HOVERED_OPACITY));
				item.setOnMouseLeaveListener((JavaScriptCallback) ev -> item.setOpacity(0));
			}

			item.setOnOpListener((JavaScriptCallback) ev ->
			{
				if (onItemSelected != null)
				{
					onItemSelected.accept(itemComposition.getId());
				}
				chatboxPanelManager.close();
			});

			x += ICON_WIDTH + PADDING;
			if (x + ICON_WIDTH >= container.getWidth())
			{
				y += ICON_HEIGHT + PADDING;
				x = PADDING;
			}

			item.revalidate();
			++idx;
		}
	}

	@Override
	public void keyPressed(KeyEvent ev)
	{
		if (!chatboxPanelManager.shouldTakeInput()) return;

		switch (ev.getKeyCode())
		{
			case KeyEvent.VK_ENTER:
				ev.consume();
				if (index > -1 && onItemSelected != null)
				{
					onItemSelected.accept(results.keySet().toArray(new Integer[0])[index]);
					chatboxPanelManager.close();
				}
				break;
			default:
				super.keyPressed(ev);
		}
	}

	@Override
	protected void close()
	{
		value("");
		results.clear();
		index = -1;
		super.close();
	}

	public WeaponChatboxSearch onItemSelected(Consumer<Integer> onItemSelected)
	{
		this.onItemSelected = onItemSelected;
		return this;
	}

	private void filterResults()
	{
		results.clear();
		index = -1;

		String search = getValue().toLowerCase();
		if (search.isEmpty()) return;

		for (int i = 0; i < client.getItemCount() && results.size() < MAX_RESULTS; i++)
		{
			int canonical = itemManager.canonicalize(i);
			if (canonical != i) continue;

			ItemComposition comp = itemManager.getItemComposition(canonical);
			String name = comp.getName().toLowerCase();
			if (name.equals("null") || !name.contains(search)) continue;

			ItemStats stats = itemManager.getItemStats(canonical);
			if (stats == null || stats.getEquipment() == null) continue;
			if (stats.getEquipment().getSlot() != WEAPON_SLOT) continue;

			if (!results.containsKey(comp.getId()))
			{
				results.put(comp.getId(), comp);
			}
		}
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.List;
import lombok.Getter;
import lombok.Setter;

@Getter
public class WeaponEntry
{
	private final int itemId;
	private String weaponName;
	private final List<TriggerGroup> groups;
	@Setter private boolean enabled;
	/** When true, this weapon's triggers do not override the matching Global (All Weapons) triggers — both play. */
	@Setter private boolean dontOverrideGlobal;

	public WeaponEntry(int itemId, String weaponName, List<TriggerGroup> groups)
	{
		this.itemId = itemId;
		this.weaponName = weaponName;
		this.groups = groups != null ? groups : new ArrayList<>();
		this.enabled = true;
		this.dontOverrideGlobal = false;
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;

/**
 * Owns the configured weapons and their lifecycle: load, add, re-point (change), copy, and remove,
 * keeping the in-memory list and {@link CustomWeaponSfxConfigStore} in sync.
 *
 * <p>Stays free of Swing and the game client: it reports a rebuild via the {@code onChanged} callback
 * and an id-collision via {@code onConflict} (with a ready-to-show message), leaving the plugin to do
 * the actual panel rebuild and warning dialog.
 */
class WeaponManager
{
	private final List<WeaponEntry> entries = new CopyOnWriteArrayList<>();
	private final CustomWeaponSfxConfigStore store;
	private final Runnable onChanged;
	private final Consumer<String> onConflict;

	WeaponManager(CustomWeaponSfxConfigStore store, Runnable onChanged, Consumer<String> onConflict)
	{
		this.store = store;
		this.onChanged = onChanged;
		this.onConflict = onConflict;
	}

	/** (Re)loads the configured weapons from storage. */
	void load()
	{
		entries.clear();
		entries.addAll(store.loadWeapons());
	}

	/** A defensive copy of the current weapons, safe to hand to the panel / other threads. */
	List<WeaponEntry> snapshot()
	{
		return new ArrayList<>(entries);
	}

	WeaponEntry find(int itemId)
	{
		for (WeaponEntry entry : entries)
		{
			if (entry.getItemId() == itemId) return entry;
		}
		return null;
	}

	void add(int itemId, String name)
	{
		if (find(itemId) != null) return;

		WeaponEntry entry = new WeaponEntry(itemId, name, new ArrayList<>());
		entries.add(entry);

		store.saveWeapon(entry);
		store.saveWeaponIds(entries);

		onChanged.run();
	}

	/**
	 * Re-points an existing weapon entry from {@code oldItemId} to {@code newItemId}, preserving its
	 * sound groups and enabled state. Because the item id is the config key, this rewrites the entry
	 * under the new id and updates the id index. No-ops if the id is unchanged; warns and aborts if the
	 * target id already has its own separate configuration.
	 */
	void change(int oldItemId, int newItemId, String newName)
	{
		if (oldItemId == newItemId) return;

		WeaponEntry old = find(oldItemId);
		if (old == null) return;

		if (find(newItemId) != null)
		{
			onConflict.accept(newName + " is already configured as a separate weapon.");
			return;
		}

		int idx = entries.indexOf(old);
		store.removeWeapon(old);

		WeaponEntry updated = new WeaponEntry(newItemId, newName, old.getGroups());
		updated.setEnabled(old.isEnabled());
		updated.setDontOverrideGlobal(old.isDontOverrideGlobal());
		entries.set(idx, updated);

		store.saveWeapon(updated);
		store.saveWeaponIds(entries);

		onChanged.run();
	}

	/**
	 * Creates a new weapon entry for {@code newItemId} with a deep copy of {@code sourceItemId}'s
	 * sound groups, enabled state, and "don't override Global" flag. No-ops if the source is gone;
	 * warns and aborts if the target id already has its own configuration.
	 */
	void copy(int sourceItemId, int newItemId, String newName)
	{
		WeaponEntry source = find(sourceItemId);
		if (source == null) return;

		if (find(newItemId) != null)
		{
			onConflict.accept(newName + " is already configured. Remove it first, or pick a different weapon to copy onto.");
			return;
		}

		WeaponEntry copy = new WeaponEntry(newItemId, newName, copyGroups(source.getGroups()));
		copy.setEnabled(source.isEnabled());
		copy.setDontOverrideGlobal(source.isDontOverrideGlobal());
		entries.add(copy);

		store.saveWeapon(copy);
		store.saveWeaponIds(entries);

		onChanged.run();
	}

	/**
	 * Moves the weapon with {@code itemId} to {@code newIndex} in the ordering and persists the new
	 * order (the id index is order-significant, so this is all that's needed). No-ops if the id is
	 * unknown or it is already at that index.
	 */
	void move(int itemId, int newIndex)
	{
		WeaponEntry entry = find(itemId);
		if (entry == null) return;

		int current = entries.indexOf(entry);
		if (current < 0) return;

		int target = Math.max(0, Math.min(newIndex, entries.size() - 1));
		if (current == target) return;

		entries.remove(current);
		entries.add(target, entry);

		store.saveWeaponIds(entries);

		onChanged.run();
	}

	void remove(int itemId)
	{
		WeaponEntry entry = find(itemId);
		if (entry != null) store.removeWeapon(entry);
		entries.removeIf(e -> e.getItemId() == itemId);
		store.saveWeaponIds(entries);

		onChanged.run();
	}

	/** Empties the in-memory list (config wiping is done separately via the store's reset). */
	void clear()
	{
		entries.clear();
	}

	/** Deep-copies a weapon's sound groups so the copy and the original share no mutable state. */
	private static List<TriggerGroup> copyGroups(List<TriggerGroup> groups)
	{
		List<TriggerGroup> out = new ArrayList<>(groups.size());
		for (TriggerGroup g : groups)
		{
			List<SoundEntry> sounds = new ArrayList<>(g.getSounds().size());
			for (SoundEntry s : g.getSounds())
				sounds.add(new SoundEntry(s.getSoundFile(), s.getVolume(), s.getWeight()));

			Set<Triggers> triggers = EnumSet.noneOf(Triggers.class);
			triggers.addAll(g.getTriggers());

			TriggerGroup copy = new TriggerGroup(triggers, sounds, g.getChance());
			copy.setName(g.getName());
			out.add(copy);
		}
		return out;
	}
}

package com.customweaponsfx;

import java.util.Collections;
import java.util.Set;

/**
 * Decides which default in-game sound effects the plugin silences.
 *
 * <p>Holds a user-configured set of sound-effect ids entered in the panel (e.g. the default weapon
 * swing/hit sounds a player wants replaced by their own SFX). The set is persisted through
 * {@link CustomWeaponSfxConfigStore} and swapped atomically so the client thread always reads a
 * consistent, immutable set. Mirrors {@link NpcExclusionFilter}.
 */
class WeaponSoundMuteFilter
{
	private final CustomWeaponSfxConfigStore store;

	/** User-configured sound-effect ids to mute. Swapped atomically. */
	private volatile Set<Integer> mutedIds = Collections.emptySet();

	WeaponSoundMuteFilter(CustomWeaponSfxConfigStore store)
	{
		this.store = store;
	}

	/** Loads the user sound-id mutes from config. */
	void load()
	{
		mutedIds = Collections.unmodifiableSet(
			CustomWeaponSfxConfigStore.parseSoundIds(store.getMutedWeaponSoundIdsRaw()));
	}

	boolean isMuted(int soundId)
	{
		return mutedIds.contains(soundId);
	}

	/** Persists and applies a raw, user-entered comma-separated sound-id string. */
	void setIds(String raw)
	{
		store.setMutedWeaponSoundIds(raw);
		mutedIds = Collections.unmodifiableSet(CustomWeaponSfxConfigStore.parseSoundIds(raw));
	}

	/** Drops the in-memory mutes (config is wiped separately via the store's reset). */
	void clear()
	{
		mutedIds = Collections.emptySet();
	}
}

package com.customweaponsfx;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class AmountConditionTest
{
	@Test
	public void greaterLessEqualMatchAsExpected()
	{
		AmountCondition gt = new AmountCondition(AmountCondition.Op.GREATER, 10);
		assertTrue(gt.matches(11));
		assertFalse(gt.matches(10));
		assertFalse(gt.matches(9));

		AmountCondition lt = new AmountCondition(AmountCondition.Op.LESS, 10);
		assertTrue(lt.matches(9));
		assertFalse(lt.matches(10));
		assertFalse(lt.matches(11));

		AmountCondition eq = new AmountCondition(AmountCondition.Op.EQUAL, 73);
		assertTrue(eq.matches(73));
		assertFalse(eq.matches(72));
		assertFalse(eq.matches(74));
	}

	@Test
	public void serializeDeserializeRoundTrips()
	{
		AmountCondition original = new AmountCondition(AmountCondition.Op.EQUAL, 73);
		AmountCondition restored = AmountCondition.deserialize(original.serialize());
		assertEquals(original.getOp(), restored.getOp());
		assertEquals(original.getValue(), restored.getValue());
	}

	@Test
	public void deserializeRejectsNullBlankAndMalformed()
	{
		assertNull(AmountCondition.deserialize(null));
		assertNull(AmountCondition.deserialize(""));
		assertNull(AmountCondition.deserialize("EQUAL"));
		assertNull(AmountCondition.deserialize("NOPE:5"));
		assertNull(AmountCondition.deserialize("EQUAL:notanumber"));
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class AttackAggregatorTest
{
	private static final List<TriggerGroup> GROUPS = new ArrayList<>();

	// Burning claws: special only, 3 hits over 2 ticks, any max-coloured splat counts as a max.
	private static final AttackProfile BURNING_CLAWS =
		new AttackProfile(3, 2, true, flags -> flags.stream().anyMatch(Boolean::booleanValue));
	// Dragon claws: special only, 4 hits (2 per tick over 2 ticks). Only the first two splats can max, so a
	// max hit requires both of the first two to be max.
	private static final AttackProfile DRAGON_CLAWS =
		new AttackProfile(4, 2, true, flags -> flags.size() >= 2 && flags.get(0) && flags.get(1));
	// Dark bow: any attack, 2 hits; count-based completion with a wide 5-tick fallback span (arrows can land
	// a couple of ticks apart at range). Max only when both splats are max.
	private static final AttackProfile DARK_BOW =
		new AttackProfile(2, 5, false, flags -> flags.stream().allMatch(Boolean::booleanValue));
	// Twinflame staff: any attack, 2 hits a tick apart, only the first hit can be max.
	private static final AttackProfile TWINFLAME =
		new AttackProfile(2, 3, false, flags -> !flags.isEmpty() && flags.get(0));

	private static int sum(int[] a)
	{
		return Arrays.stream(a).sum();
	}

	@Test
	public void clawsAggregateAcrossTwoTicksWithAnySplatMax()
	{
		AttackAggregator agg = new AttackAggregator();
		agg.begin(555, 10, BURNING_CLAWS, GROUPS, false);
		agg.add(Arrays.asList(18, 12), Arrays.asList(false, false), true, false);
		assertFalse("not complete: only 2 of 3 hits", agg.isComplete(10));

		agg.add(Arrays.asList(15), Arrays.asList(true), false, false); // tail splat carries max, lost spec flag
		assertTrue(agg.isComplete(11));

		AttackOutcome o = agg.buildOutcome();
		assertTrue("spec flag OR-ed across the attack", o.wasSpec);
		assertTrue("any max-coloured splat -> max hit", o.allMax);
		assertEquals(18 + 12 + 15, sum(o.amounts));
	}

	@Test
	public void dragonClawsAreMaxOnlyWhenBothOfTheFirstTwoSplatsAreMax()
	{
		// 2 splats on tick 10, 2 on tick 11; completes by count (4) on the second tick.
		// Both of the first two splats max -> a max hit.
		AttackAggregator bothMax = new AttackAggregator();
		bothMax.begin(13652, 10, DRAGON_CLAWS, GROUPS, false);
		bothMax.add(Arrays.asList(40, 20), Arrays.asList(true, true), true, false);
		assertFalse("only 2 of 4 hits", bothMax.isComplete(10));
		bothMax.add(Arrays.asList(10, 11), Arrays.asList(false, false), false, false);
		assertTrue(bothMax.isComplete(11));
		AttackOutcome o = bothMax.buildOutcome();
		assertTrue("both of the first two splats max -> max hit", o.allMax);
		assertTrue("spec flag carried across the ticks", o.wasSpec);
		assertEquals(81, sum(o.amounts));

		// Only the first splat max -> not a max hit.
		AttackAggregator firstOnly = new AttackAggregator();
		firstOnly.begin(13652, 10, DRAGON_CLAWS, GROUPS, false);
		firstOnly.add(Arrays.asList(40, 20), Arrays.asList(true, false), true, false);
		firstOnly.add(Arrays.asList(10, 11), Arrays.asList(false, false), false, false);
		assertFalse("only the first splat max -> not a max hit", firstOnly.buildOutcome().allMax);

		// Only a later (3rd/4th) splat flagged max -> not a max hit; those splats never actually max for claws.
		AttackAggregator laterOnly = new AttackAggregator();
		laterOnly.begin(13652, 10, DRAGON_CLAWS, GROUPS, false);
		laterOnly.add(Arrays.asList(40, 20), Arrays.asList(false, false), true, false);
		laterOnly.add(Arrays.asList(10, 11), Arrays.asList(true, true), false, false);
		assertFalse("first two not max -> not a max hit", laterOnly.buildOutcome().allMax);
	}

	@Test
	public void darkBowSameTickPairCompletesImmediately()
	{
		// Both arrows land on tick 10 -> hit count reached at once, no need to wait a tick.
		AttackAggregator agg = new AttackAggregator();
		agg.begin(11235, 10, DARK_BOW, GROUPS, false);
		agg.add(Arrays.asList(20, 26), Arrays.asList(true, true), false, false);
		assertTrue(agg.isComplete(10));

		AttackOutcome o = agg.buildOutcome();
		assertFalse(o.wasSpec);
		assertTrue("both splats max -> max hit", o.allMax);
		assertEquals(46, sum(o.amounts));
	}

	@Test
	public void darkBowSplitPairCompletesOnSecondTick()
	{
		AttackAggregator agg = new AttackAggregator();
		agg.begin(11235, 10, DARK_BOW, GROUPS, false);
		agg.add(Arrays.asList(20), Arrays.asList(true), false, false);
		assertFalse("only one arrow so far", agg.isComplete(10));
		agg.add(Arrays.asList(6), Arrays.asList(false), false, false);
		assertTrue(agg.isComplete(11));

		AttackOutcome o = agg.buildOutcome();
		assertFalse("only one splat maxed -> not a max hit for the dark bow", o.allMax);
		assertEquals(26, sum(o.amounts));
	}

	@Test
	public void darkBowTwoTickGapWaitsForTheSecondArrowInsteadOfFiringTwice()
	{
		// Regression: at range the arrows can land two ticks apart (10 and 12). The wide fallback span must not
		// complete the attack at tick 11 with only the first arrow — that split it into two firings.
		AttackAggregator agg = new AttackAggregator();
		agg.begin(11235, 10, DARK_BOW, GROUPS, false);
		agg.add(Arrays.asList(20), Arrays.asList(true), false, false);
		assertFalse("tick 11: still waiting for the second arrow", agg.isComplete(11));
		assertFalse("tick 12 before the arrow: still waiting", agg.isComplete(12));

		agg.add(Arrays.asList(26), Arrays.asList(true), false, false); // second arrow lands on tick 12
		assertTrue("both arrows in -> completes by count", agg.isComplete(12));
		assertTrue("both splats max", agg.buildOutcome().allMax);
		assertEquals(46, sum(agg.buildOutcome().amounts));
	}

	@Test
	public void tickSpanFallbackCompletesWhenAHitIsMissing()
	{
		// Dark bow but only one arrow ever lands (e.g. target died): the tick-span fallback completes it after
		// the span (firstTick 10 + span 5 - 1 = 14), well within the dark bow's ≥8-tick attack cadence.
		AttackAggregator agg = new AttackAggregator();
		agg.begin(11235, 10, DARK_BOW, GROUPS, false);
		agg.add(Arrays.asList(30), Arrays.asList(false), false, true);
		assertFalse("not yet: span has not elapsed and only one hit landed", agg.isComplete(13));
		assertTrue("span elapsed -> complete even though only one hit landed", agg.isComplete(14));
		assertTrue(agg.buildOutcome().isKill);
	}

	@Test
	public void twinflameIsMaxOnlyWhenTheFirstHitIsMax()
	{
		// First hit max, second hit not -> a max hit (only the first hit can max).
		AttackAggregator first = new AttackAggregator();
		first.begin(30634, 10, TWINFLAME, GROUPS, false);
		first.add(Arrays.asList(30), Arrays.asList(true), false, false);
		first.add(Arrays.asList(12), Arrays.asList(false), false, false); // second hit lands a tick later
		assertTrue(first.isComplete(11));
		AttackOutcome maxed = first.buildOutcome();
		assertTrue("first hit max -> max hit", maxed.allMax);
		assertEquals(42, sum(maxed.amounts));

		// First hit not max -> not a max hit, regardless of the second.
		AttackAggregator second = new AttackAggregator();
		second.begin(30634, 10, TWINFLAME, GROUPS, false);
		second.add(Arrays.asList(20), Arrays.asList(false), false, false);
		second.add(Arrays.asList(12), Arrays.asList(true), false, false);
		assertFalse("first hit not max -> not a max hit", second.buildOutcome().allMax);
	}

	@Test
	public void isActiveForOnlyMatchesTheOpenWeapon()
	{
		AttackAggregator agg = new AttackAggregator();
		assertFalse(agg.isActiveFor(11235));
		agg.begin(11235, 10, DARK_BOW, GROUPS, false);
		assertTrue(agg.isActiveFor(11235));
		assertFalse(agg.isActiveFor(555));
		agg.reset();
		assertFalse(agg.isActiveFor(11235));
	}
}

package com.customweaponsfx;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class AttackWeaponTrackerTest
{
	private static final int SCYTHE = 22325;
	private static final int BOW = 12926;
	private static final int UNARMED = AttackWeaponTracker.NONE;

	@Test
	public void freshTrackerFallsBackToCurrentlyEquippedWeapon()
	{
		AttackWeaponTracker tracker = new AttackWeaponTracker();
		assertEquals(SCYTHE, tracker.resolveWeaponId(SCYTHE));
	}

	@Test
	public void capturedWeaponIsUsedForALandingHitsplat()
	{
		AttackWeaponTracker tracker = new AttackWeaponTracker();
		tracker.onAttack(SCYTHE);
		assertEquals(SCYTHE, tracker.resolveWeaponId(SCYTHE));
	}

	@Test
	public void capturedWeaponWinsOverACurrentSwap()
	{
		// Fire a bow, then swap to a scythe while the arrow is mid-flight.
		// The landing hitsplat should still be attributed to the bow.
		AttackWeaponTracker tracker = new AttackWeaponTracker();
		tracker.onAttack(BOW);
		assertEquals(BOW, tracker.resolveWeaponId(SCYTHE));
	}

	// ---- the regression this protects ---------------------------------------------

	@Test
	public void unarmedAttackAfterUnequipDoesNotReuseTheOldWeapon()
	{
		AttackWeaponTracker tracker = new AttackWeaponTracker();
		tracker.onAttack(SCYTHE);            // attacked with a weapon
		tracker.onAttack(UNARMED);           // unequipped, then punched bare-fisted
		// Resolution must report unarmed, not the stale scythe, so no weapon SFX fires.
		assertEquals(UNARMED, tracker.resolveWeaponId(UNARMED));
	}

	@Test
	public void unarmedCaptureClearsAPreviouslyCapturedWeapon()
	{
		AttackWeaponTracker tracker = new AttackWeaponTracker();
		tracker.onAttack(SCYTHE);
		tracker.onAttack(UNARMED);
		// Even if some equipped weapon is reported at hitsplat-time, an unarmed swing
		// cleared the capture so it must not resurrect the scythe.
		assertEquals(BOW, tracker.resolveWeaponId(BOW));
	}

	@Test
	public void resetClearsCapturedWeapon()
	{
		AttackWeaponTracker tracker = new AttackWeaponTracker();
		tracker.onAttack(SCYTHE);
		tracker.reset();
		assertEquals(UNARMED, tracker.resolveWeaponId(UNARMED));
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class CustomWeaponSfxConfigStoreTest
{
	/** In-memory {@link CustomWeaponSfxConfigStore.Backend} mirroring ConfigManager string semantics. */
	private static final class MapBackend implements CustomWeaponSfxConfigStore.Backend
	{
		final Map<String, String> map = new HashMap<>();

		@Override
		public String get(String key)
		{
			return map.get(key);
		}

		@Override
		public void set(String key, Object value)
		{
			// ConfigManager persists everything as strings; mirror that here.
			map.put(key, String.valueOf(value));
		}

		@Override
		public void unset(String key)
		{
			map.remove(key);
		}
	}

	private MapBackend backend;
	private CustomWeaponSfxConfigStore store;

	@Before
	public void setUp()
	{
		backend = new MapBackend();
		store = new CustomWeaponSfxConfigStore(backend);
	}

	private static TriggerGroup group(java.util.Set<Triggers> triggers, int chance, SoundEntry... sounds)
	{
		List<SoundEntry> list = new ArrayList<>();
		for (SoundEntry s : sounds) list.add(s);
		return new TriggerGroup(triggers, list, chance);
	}

	private static void assertGroupEquals(TriggerGroup expected, TriggerGroup actual)
	{
		assertEquals(expected.getTriggers(), actual.getTriggers());
		assertEquals(expected.getAmountConditions().keySet(), actual.getAmountConditions().keySet());
		for (Triggers t : expected.getAmountConditions().keySet())
		{
			assertEquals(expected.getAmountCondition(t).getOp(), actual.getAmountCondition(t).getOp());
			assertEquals(expected.getAmountCondition(t).getValue(), actual.getAmountCondition(t).getValue());
		}
		assertEquals(expected.getChance(), actual.getChance());
		assertEquals(expected.getSounds().size(), actual.getSounds().size());
		for (int i = 0; i < expected.getSounds().size(); i++)
		{
			assertEquals(expected.getSounds().get(i).getSoundFile(), actual.getSounds().get(i).getSoundFile());
			assertEquals(expected.getSounds().get(i).getVolume(), actual.getSounds().get(i).getVolume());
			assertEquals(expected.getSounds().get(i).getWeight(), actual.getSounds().get(i).getWeight(), 0.0001);
		}
	}

	@Test
	public void weaponRoundTripsThroughSaveAndLoad()
	{
		List<TriggerGroup> groups = new ArrayList<>();
		groups.add(group(EnumSet.of(Triggers.REGULAR_HIT, Triggers.KILL), 80,
			new SoundEntry("bundled:bonk", 50, 0.5), new SoundEntry("my-clip", 100, 2.5)));
		groups.add(group(EnumSet.of(Triggers.SPECIAL_MAX), 25, new SoundEntry("", 75)));

		WeaponEntry entry = new WeaponEntry(1234, "Test Weapon", groups);
		entry.setEnabled(false);
		entry.setDontOverrideGlobal(true);

		store.saveWeapon(entry);
		store.saveWeaponIds(java.util.Collections.singletonList(entry));

		List<WeaponEntry> loaded = store.loadWeapons();
		assertEquals(1, loaded.size());

		WeaponEntry back = loaded.get(0);
		assertEquals(1234, back.getItemId());
		assertEquals("Test Weapon", back.getWeaponName());
		assertFalse(back.isEnabled());
		assertTrue(back.isDontOverrideGlobal());
		assertEquals(2, back.getGroups().size());
		assertGroupEquals(groups.get(0), back.getGroups().get(0));
		assertGroupEquals(groups.get(1), back.getGroups().get(1));
	}

	@Test
	public void weaponWithoutPerWeaponFlagInheritsLegacyGlobalDontOverride()
	{
		// A weapon saved before "Don't override Global" became per-weapon: it has groups + id index but
		// no _dontOverrideGlobal key, while the old global toggle was on.
		backend.set("dontOverrideGlobal", true);
		backend.set("specWeapon_555_groupCount", 0);
		backend.set("specWeaponIds", "555");

		WeaponEntry back = store.loadWeapons().get(0);
		assertTrue("legacy global value should carry over to the weapon", back.isDontOverrideGlobal());
	}

	@Test
	public void legacyDontOverrideMigratesForwardAndIsRemoved()
	{
		// Same legacy setup, but assert the one-time migration writes the value onto the weapon's own key
		// and clears the legacy global key, so future loads no longer depend on the fallback.
		backend.set("dontOverrideGlobal", true);
		backend.set("specWeapon_555_groupCount", 0);
		backend.set("specWeaponIds", "555");

		store.loadWeapons();

		assertEquals("per-weapon key should be persisted", "true", backend.map.get("specWeapon_555_dontOverrideGlobal"));
		assertNull("legacy global key should be absorbed", backend.map.get("dontOverrideGlobal"));

