package com.customweaponsfx;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class HitAggregatorTest
{
	private static DeferredHit hit(int key, List<TriggerGroup> groups, boolean wasSpec, int amount, boolean isMax, int tick)
	{
		return new DeferredHit(key, groups, false, wasSpec, amount, isMax, tick, null);
	}

	private static PendingAttack only(List<PendingAttack> attacks)
	{
		assertEquals(1, attacks.size());
		return attacks.get(0);
	}

	private static PendingAttack withGroups(List<PendingAttack> attacks, List<TriggerGroup> groups)
	{
		return attacks.stream().filter(a -> a.groups == groups).findFirst().orElseThrow(AssertionError::new);
	}

	// ---- PendingAttack.collapse ----------------------------------------------------

	@Test
	public void collapseFlagsAllMaxWhenEveryHitIsMax()
	{
		PendingAttack attack = new PendingAttack(new ArrayList<>());
		attack.wasSpec = true;
		attack.amounts.add(5);
		attack.amounts.add(3);
		attack.isMaxList.add(true);
		attack.isMaxList.add(true);

		AttackOutcome o = attack.collapse(false);
		assertTrue(o.wasSpec);
		assertTrue(o.anyHit);
		assertFalse(o.allZero);
		assertTrue(o.allMax);
		assertEquals(5, o.maxAmount);
		assertFalse(o.isKill);
	}

	@Test
	public void collapseFlagsAllZeroOnlyWhenEveryHitIsZero()
	{
		PendingAttack attack = new PendingAttack(new ArrayList<>());
		attack.amounts.add(0);
		attack.amounts.add(0);
		attack.isMaxList.add(false);
		attack.isMaxList.add(false);

		AttackOutcome o = attack.collapse(false);
		assertFalse(o.anyHit);
		assertTrue(o.allZero);
		assertFalse(o.allMax);
		assertEquals(0, o.maxAmount);
	}

	@Test
	public void collapseMixedHitIsNeitherAllMaxNorAllZero()
	{
		PendingAttack attack = new PendingAttack(new ArrayList<>());
		attack.amounts.add(5);
		attack.amounts.add(0);
		attack.isMaxList.add(true);
		attack.isMaxList.add(false);

		AttackOutcome o = attack.collapse(false);
		assertTrue(o.anyHit);
		assertFalse(o.allZero);
		assertFalse(o.allMax);
		assertEquals(5, o.maxAmount);
	}

	@Test
	public void collapsePassesThroughIsKill()
	{
		PendingAttack attack = new PendingAttack(new ArrayList<>());
		attack.amounts.add(7);
		attack.isMaxList.add(false);
		assertTrue(attack.collapse(true).isKill);
	}

	// ---- HitAggregator.drainByTick -------------------------------------------------

	@Test
	public void emptyAggregatorDrainsToNothing()
	{
		HitAggregator agg = new HitAggregator();
		assertTrue(agg.isEmpty());
		assertTrue(agg.drainByTick().isEmpty());
	}

	@Test
	public void hitsSharingTickAndKeyAggregateIntoOneAttack()
	{
		List<TriggerGroup> groups = new ArrayList<>();
		HitAggregator agg = new HitAggregator();
		agg.add(hit(1, groups, false, 5, true, 10));
		agg.add(hit(1, groups, false, 3, false, 10));

		List<List<PendingAttack>> byTick = agg.drainByTick();
		assertEquals(1, byTick.size());
		PendingAttack attack = only(byTick.get(0));
		assertEquals(2, attack.amounts.size());
		assertEquals(5, (int) attack.amounts.get(0));
		assertEquals(3, (int) attack.amounts.get(1));
		assertSame(groups, attack.groups);
	}

	@Test
	public void distinctKeysInSameTickBecomeSeparateAttacks()
	{
		List<TriggerGroup> weapon = new ArrayList<>();
		List<TriggerGroup> received = new ArrayList<>();
		HitAggregator agg = new HitAggregator();
		agg.add(hit(100, weapon, true, 9, true, 10));
		agg.add(hit(-2, received, false, 0, false, 10));

		List<PendingAttack> tick = agg.drainByTick().get(0);
		assertEquals(2, tick.size());
		assertTrue(withGroups(tick, weapon).wasSpec);
		assertFalse(withGroups(tick, received).wasSpec);
		assertEquals(0, (int) withGroups(tick, received).amounts.get(0));
	}

	@Test
	public void separateTicksAreReturnedInAscendingOrder()
	{
		List<TriggerGroup> groups = new ArrayList<>();
		HitAggregator agg = new HitAggregator();
		// add out of order to prove the drain sorts by tick
		agg.add(hit(1, groups, false, 5, false, 12));
		agg.add(hit(1, groups, false, 6, false, 11));

		List<List<PendingAttack>> byTick = agg.drainByTick();
		assertEquals(2, byTick.size());
		assertEquals(6, (int) only(byTick.get(0)).amounts.get(0)); // tick 11 first
		assertEquals(5, (int) only(byTick.get(1)).amounts.get(0)); // tick 12 second
	}

	@Test
	public void drainClearsTheBuffer()
	{
		HitAggregator agg = new HitAggregator();
		agg.add(hit(1, new ArrayList<>(), false, 5, false, 10));
		assertFalse(agg.isEmpty());
		agg.drainByTick();
		assertTrue(agg.isEmpty());
		assertTrue(agg.drainByTick().isEmpty());
	}
}

package com.customweaponsfx;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.NPC;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Covers which NPC hitsplats the plugin ignores: the built-in id blocklist plus the user's
 * configured id/name exclusions, including case-insensitive name matching and persistence through
 * the config store.
 */
public class NpcExclusionFilterTest
{
	/** A built-in excluded id (see {@code NpcExclusionFilter.EXCLUDED_NPC_IDS}). */
	private static final int BUILT_IN_EXCLUDED = 11706;

	/** In-memory backend mirroring ConfigManager's string-only persistence. */
	private static final class MapBackend implements CustomWeaponSfxConfigStore.Backend
	{
		final Map<String, String> map = new HashMap<>();

		@Override public String get(String key) { return map.get(key); }
		@Override public void set(String key, Object value) { map.put(key, String.valueOf(value)); }
		@Override public void unset(String key) { map.remove(key); }
	}

	private MapBackend backend;
	private CustomWeaponSfxConfigStore store;
	private NpcExclusionFilter filter;

	@Before
	public void setUp()
	{
		backend = new MapBackend();
		store = new CustomWeaponSfxConfigStore(backend);
		filter = new NpcExclusionFilter(store);
	}

	private static NPC npc(int id, String name)
	{
		NPC npc = mock(NPC.class);
		when(npc.getId()).thenReturn(id);
		when(npc.getName()).thenReturn(name);
		return npc;
	}

	@Test
	public void builtInIdIsExcludedWithoutAnyConfig()
	{
		assertTrue(filter.isExcluded(npc(BUILT_IN_EXCLUDED, "Whatever")));
	}

	@Test
	public void unconfiguredNpcIsNotExcluded()
	{
		assertFalse(filter.isExcluded(npc(99, "Goblin")));
	}

	@Test
	public void userConfiguredIdIsExcluded()
	{
		filter.setIds("99, 100");
		assertTrue(filter.isExcluded(npc(99, "Goblin")));
		assertTrue(filter.isExcluded(npc(100, "Goblin")));
		assertFalse(filter.isExcluded(npc(101, "Goblin")));
	}

	@Test
	public void userConfiguredNameIsExcludedCaseInsensitivelyAndTrimmed()
	{
		filter.setNames("Vorkath");
		assertTrue("exact", filter.isExcluded(npc(1, "Vorkath")));
		assertTrue("different case", filter.isExcluded(npc(1, "VORKATH")));
		assertTrue("surrounding whitespace on the target name", filter.isExcluded(npc(1, "  vorkath ")));
		assertFalse(filter.isExcluded(npc(1, "Zulrah")));
	}

	@Test
	public void nullNpcNameDoesNotMatchAndDoesNotThrow()
	{
		filter.setNames("Vorkath");
		assertFalse(filter.isExcluded(npc(1, null)));
	}

	@Test
	public void setIdsPersistsThroughTheStore()
	{
		filter.setIds("12345");
		assertTrue(store.getExcludedNpcIdsRaw().contains("12345"));

		// A fresh filter loading from the same store sees the persisted exclusion.
		NpcExclusionFilter reloaded = new NpcExclusionFilter(store);
		reloaded.load();
		assertTrue(reloaded.isExcluded(npc(12345, "Boss")));
	}

	@Test
	public void setNamesPersistsThroughTheStore()
	{
		filter.setNames("Zulrah");
		NpcExclusionFilter reloaded = new NpcExclusionFilter(store);
		reloaded.load();
		assertTrue(reloaded.isExcluded(npc(1, "Zulrah")));
	}

	@Test
	public void clearDropsUserExclusionsButKeepsBuiltIns()
	{
		filter.setIds("99");
		filter.setNames("Vorkath");

		filter.clear();

		assertFalse("user id exclusion gone", filter.isExcluded(npc(99, "Goblin")));
		assertFalse("user name exclusion gone", filter.isExcluded(npc(1, "Vorkath")));
		assertTrue("built-in still excluded", filter.isExcluded(npc(BUILT_IN_EXCLUDED, "x")));
	}
}

package com.customweaponsfx;

import net.runelite.api.Actor;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Covers the landing-side matching: a hitsplat is attributed to the weapon that launched the
 * projectile which caused it, keyed on the projectile's target and arrival cycle. Matching must be
 * independent of projectile travel distance, must not be stolen by an instant melee hit while a shot
 * is still clearly in flight, and must consume projectiles oldest-first per target.
 */
public class ProjectileWeaponTrackerTest
{
	private static final int STAFF = 11791;
	private static final int BOW   = 12926;
	private static final int START_CYCLE = 5000;

	private final ProjectileWeaponTracker tracker = new ProjectileWeaponTracker();

	// ---- recording dedup -----------------------------------------------------------------------

	@Test
	public void perFrameSpawnIsRecordedOnlyOnce()
	{
		assertFalse("first sighting is the spawn", tracker.hasSeen(START_CYCLE));
		assertTrue("subsequent frames are ignored", tracker.hasSeen(START_CYCLE));
		assertTrue(tracker.hasSeen(START_CYCLE));
	}

	// ---- target matching -----------------------------------------------------------------------

	@Test
	public void landingHitWithNoTrackedProjectileFallsBack()
	{
		assertNull(tracker.matchAndRemove(mock(Actor.class), 100));
	}

	@Test
	public void hitOnTargetIsAttributedToTheProjectileWeapon()
	{
		Actor target = mock(Actor.class);
		tracker.onProjectileSpawned(STAFF, target, null, 100, 0, false);

		ProjectileWeaponTracker.TrackedProjectile tp = tracker.matchAndRemove(target, 100);
		assertNotNull(tp);
		assertEquals(STAFF, tp.weaponId);
	}

	@Test
	public void matchedProjectileIsConsumed()
	{
		Actor target = mock(Actor.class);
		tracker.onProjectileSpawned(STAFF, target, null, 100, 0, false);

		assertNotNull(tracker.matchAndRemove(target, 100));
		assertNull("a projectile matches a single hit only", tracker.matchAndRemove(target, 100));
	}

	@Test
	public void hitOnADifferentTargetDoesNotMatch()
	{
		Actor target = mock(Actor.class);
		Actor other  = mock(Actor.class);
		tracker.onProjectileSpawned(STAFF, target, null, 100, 0, false);

		assertNull(tracker.matchAndRemove(other, 100));
	}

	// ---- arrival timing (distance independence) ------------------------------------------------

	@Test
	public void projectileStillClearlyInFlightIsNotMatched()
	{
		// Lands at cycle 200; a hit now (cycle 100) is 100 cycles (~3 ticks) early. An instant melee
		// hit landing meanwhile must NOT steal the in-flight shot, so this returns null (caller falls
		// back to the melee weapon).
		Actor target = mock(Actor.class);
		tracker.onProjectileSpawned(STAFF, target, null, 200, 0, false);

		assertNull(tracker.matchAndRemove(target, 100));
	}

	@Test
	public void projectileAboutToLandWithinSlackIsMatched()
	{
		// Lands at 120, hit at 100 -> 20 cycles (< one tick) early; treated as arrived.
		Actor target = mock(Actor.class);
		tracker.onProjectileSpawned(STAFF, target, null, 120, 0, false);

		assertNotNull(tracker.matchAndRemove(target, 100));
	}

	@Test
	public void longRangeShotLandingLateStillMatches()
	{
		// Lands at 100, hit not processed until 200 (a hitsplat a few ticks after a long-range shot
		// reaches the target). Distance/lateness must not cause a miss.
		Actor target = mock(Actor.class);
		tracker.onProjectileSpawned(STAFF, target, null, 100, 0, false);

		assertNotNull(tracker.matchAndRemove(target, 200));
	}

	// ---- FIFO per target -----------------------------------------------------------------------

	@Test
	public void multipleShotsAtSameTargetAreConsumedOldestFirst()
	{
		Actor target = mock(Actor.class);
		tracker.onProjectileSpawned(BOW,   target, null, 100, 1, false); // fired first
		tracker.onProjectileSpawned(STAFF, target, null, 100, 2, false); // fired second

		assertEquals(BOW,   tracker.matchAndRemove(target, 100).weaponId);
		assertEquals(STAFF, tracker.matchAndRemove(target, 100).weaponId);
		assertNull(tracker.matchAndRemove(target, 100));
	}

	// ---- spec flag carried through -------------------------------------------------------------

	@Test
	public void specFlagIsCarriedFromSpawnToLanding()
	{
		Actor target = mock(Actor.class);
		tracker.onProjectileSpawned(BOW, target, null, 100, 0, true);

		ProjectileWeaponTracker.TrackedProjectile tp = tracker.matchAndRemove(target, 100);
		assertNotNull(tp);
		assertTrue(tp.wasSpec);
	}

	// ---- AoE (no target actor) matched by world tile -------------------------------------------

	@Test
	public void aoeProjectileIsMatchedByWorldTile()
	{
		WorldPoint tile = new WorldPoint(3200, 3200, 0);
		Actor hit = mock(Actor.class);
		when(hit.getWorldLocation()).thenReturn(tile);

		tracker.onProjectileSpawned(STAFF, null, tile, 100, 0, false);

		ProjectileWeaponTracker.TrackedProjectile tp = tracker.matchAndRemove(hit, 100);
		assertNotNull(tp);
		assertEquals(STAFF, tp.weaponId);
	}

	@Test
	public void aoeProjectileOnAnotherTileDoesNotMatch()
	{
		Actor hit = mock(Actor.class);
		when(hit.getWorldLocation()).thenReturn(new WorldPoint(3200, 3200, 0));

		tracker.onProjectileSpawned(STAFF, null, new WorldPoint(3205, 3205, 0), 100, 0, false);

		assertNull(tracker.matchAndRemove(hit, 100));
	}

	// ---- pruning / leak-safety -----------------------------------------------------------------

	@Test
	public void projectileIsKeptUntilItsTtlElapses()
	{
		Actor target = mock(Actor.class);
		tracker.hasSeen(START_CYCLE);
		tracker.onProjectileSpawned(STAFF, target, null, 100, 0, false);

		tracker.prune(CustomWeaponSfxPlugin.PROJECTILE_TTL_TICKS);     // within TTL
		assertNotNull("entry within TTL is retained", tracker.matchAndRemove(target, 100));
	}

	@Test
	public void undeliveredProjectileIsPrunedSoNothingLeaks()
	{
		Actor target = mock(Actor.class);
		tracker.hasSeen(START_CYCLE);
		tracker.onProjectileSpawned(STAFF, target, null, 100, 0, false);

		tracker.prune(CustomWeaponSfxPlugin.PROJECTILE_TTL_TICKS + 1); // past TTL
		assertNull("pruned entry no longer matches", tracker.matchAndRemove(target, 100));
		assertFalse("dedup set cleared when nothing is tracked", tracker.hasSeen(START_CYCLE));
	}

	// ---- reset ---------------------------------------------------------------------------------

	@Test
	public void resetClearsTrackedProjectilesAndDedup()
	{
		Actor target = mock(Actor.class);
		tracker.hasSeen(START_CYCLE);
		tracker.onProjectileSpawned(STAFF, target, null, 100, 0, false);

		tracker.reset();
		assertFalse(tracker.hasSeen(START_CYCLE));
		assertNull(tracker.matchAndRemove(target, 100));
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class SoundSelectionTest
{
	@Test
	public void allZeroWeightsPickNothing()
	{
		List<SoundEntry> sounds = Arrays.asList(
			new SoundEntry("a", 75, 0),
			new SoundEntry("b", 75, 0));
		assertNull(SoundPlayer.pickWeighted(sounds));
	}

	@Test
	public void zeroWeightSoundIsNeverPicked()
	{
		List<SoundEntry> sounds = Arrays.asList(
			new SoundEntry("never", 75, 0),
			new SoundEntry("always", 75, 1.0));
		for (int i = 0; i < 1000; i++)
			assertEquals("always", SoundPlayer.pickWeighted(sounds).getSoundFile());
	}

	@Test
	public void weightsRoughlyMatchObservedDistribution()
	{
		// 3:1 weighting should land near 75% / 25% over many rolls.
		List<SoundEntry> sounds = Arrays.asList(
			new SoundEntry("heavy", 75, 1.5),
			new SoundEntry("light", 75, 0.5));

		Map<String, Integer> counts = new HashMap<>();
		int n = 100_000;
		for (int i = 0; i < n; i++)
		{
			String f = SoundPlayer.pickWeighted(sounds).getSoundFile();
			counts.merge(f, 1, Integer::sum);
		}

		double heavyRatio = counts.getOrDefault("heavy", 0) / (double) n;
		assertTrue("heavy ratio was " + heavyRatio, heavyRatio > 0.72 && heavyRatio < 0.78);
	}

	@Test
	public void everySoundIsReachable()
	{
		List<SoundEntry> sounds = new ArrayList<>(Arrays.asList(
			new SoundEntry("a", 75, 0.1),
			new SoundEntry("b", 75, 0.1),
			new SoundEntry("c", 75, 0.1)));

		Map<String, Integer> seen = new HashMap<>();
		for (int i = 0; i < 1000; i++)
			seen.merge(SoundPlayer.pickWeighted(sounds).getSoundFile(), 1, Integer::sum);

		assertTrue(seen.containsKey("a"));
		assertTrue(seen.containsKey("b"));
		assertTrue(seen.containsKey("c"));
	}
}

package com.customweaponsfx;

import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Covers the special-attack detection state machine: a spec is "fired" when energy drops below the
 * last seen value, the firing weapon is remembered for a short window, and a window that never
 * produces a hitsplat expires so it can't taint a later normal attack.
 */
public class SpecAttackTrackerTest
{
	private static final int DRAGON_DAGGER = 1215;

	// ---- drop detection ------------------------------------------------------------------------

	@Test
	public void dropOnTheVeryFirstTickIsNotDetectedWithoutInit()
	{
		// A fresh tracker has no baseline, so the first tick only seeds it — no false positive.
		SpecAttackTracker tracker = new SpecAttackTracker();
		assertFalse(tracker.onTick(50, 1));
	}

	@Test
	public void dropAfterInitIsDetected()
	{
		SpecAttackTracker tracker = new SpecAttackTracker();
		tracker.init(100);
		assertTrue("spec energy fell from 100 to 50", tracker.onTick(50, 1));
	}

	@Test
	public void steadyEnergyIsNotASpec()
	{
		SpecAttackTracker tracker = new SpecAttackTracker();
		tracker.init(100);
		assertFalse(tracker.onTick(100, 1));
	}

	@Test
	public void regeneratingEnergyIsNotASpec()
	{
		SpecAttackTracker tracker = new SpecAttackTracker();
		tracker.init(50);
		assertFalse("energy climbing back up must not register as a fire", tracker.onTick(60, 1));
	}

	@Test
	public void consecutiveDropsAreEachDetected()
	{
		SpecAttackTracker tracker = new SpecAttackTracker();
		tracker.init(100);
		assertTrue(tracker.onTick(75, 1));
		assertFalse("no further drop", tracker.onTick(75, 2));
		assertTrue("a second spec drains it again", tracker.onTick(50, 3));
	}

	// ---- the spec window -----------------------------------------------------------------------

	@Test
	public void freshTrackerHasNoOpenWindow()
	{
		assertFalse(new SpecAttackTracker().wasSpec());
	}

	@Test
	public void armOpensTheWindow()
	{
		SpecAttackTracker tracker = new SpecAttackTracker();
		tracker.arm(DRAGON_DAGGER, 5);
		assertTrue(tracker.wasSpec());
	}

	@Test
	public void clearWindowClosesIt()
	{
		SpecAttackTracker tracker = new SpecAttackTracker();
		tracker.arm(DRAGON_DAGGER, 5);
		tracker.clearWindow();
		assertFalse(tracker.wasSpec());
	}

	// ---- window expiry -------------------------------------------------------------------------

	@Test
	public void windowSurvivesUpToTheTimeoutBoundary()
	{
		SpecAttackTracker tracker = new SpecAttackTracker();
		tracker.init(100);
		tracker.arm(DRAGON_DAGGER, 5);
		// 15 - 5 == 10 == TIMEOUT_TICKS; not strictly greater, so the window is still open.
		tracker.onTick(100, 15);
		assertTrue(tracker.wasSpec());
	}

	@Test
	public void staleWindowExpiresPastTheTimeout()
	{
		SpecAttackTracker tracker = new SpecAttackTracker();
		tracker.init(100);
		tracker.arm(DRAGON_DAGGER, 5);
		// 16 - 5 == 11 > TIMEOUT_TICKS: a spec that never landed must not taint a later attack.
		tracker.onTick(100, 16);
		assertFalse(tracker.wasSpec());
	}

	// ---- reset ---------------------------------------------------------------------------------

	@Test
	public void resetClosesTheWindowAndDropsTheBaseline()
	{
		SpecAttackTracker tracker = new SpecAttackTracker();
		tracker.init(100);
		tracker.arm(DRAGON_DAGGER, 5);

		tracker.reset();
		assertFalse("window cleared", tracker.wasSpec());
		// Baseline cleared too: the first post-reset tick only re-seeds, it can't fire.
		assertFalse(tracker.onTick(20, 6));
	}
}

package com.customweaponsfx;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * Covers the launch-side fix: a projectile fired on a tick must be attributed to the weapon held at
 * the <em>start</em> of that tick, even if the player swaps weapons later in the same tick (the
 * cast-and-switch-right-away case). {@code ProjectileMoved} fires after the tick's GameTick, so the
 * snapshot must be one game tick behind live equipment.
 */
public class TickWeaponSnapshotTest
{
	private static final int STAFF = 29796 - 1; // a magic/ranged weapon
	private static final int MELEE = 29796;      // the weapon swapped to
	private static final int NONE  = TickWeaponSnapshot.NONE;

	@Test
	public void launchWeaponIsNoneBeforeAnyTick()
	{
		assertEquals(NONE, new TickWeaponSnapshot().launchWeapon());
	}

	@Test
	public void initSeedsLaunchWeaponSoEarlyShotsAreAttributed()
	{
		TickWeaponSnapshot snap = new TickWeaponSnapshot();
		snap.init(STAFF);
		assertEquals(STAFF, snap.launchWeapon());
	}

	@Test
	public void steadyStateReturnsTheEquippedWeapon()
	{
		TickWeaponSnapshot snap = new TickWeaponSnapshot();
		snap.init(STAFF);
		snap.onGameTick(STAFF);
		snap.onGameTick(STAFF);
		assertEquals(STAFF, snap.launchWeapon());
	}

	/** The regression: cast with the staff and swap to a melee weapon on the same tick. By the time
	 *  this tick's GameTick runs, equipment already reads the melee weapon — but the shot used the staff. */
	@Test
	public void sameTickCastThenSwapAttributesTheShotToTheStaff()
	{
		TickWeaponSnapshot snap = new TickWeaponSnapshot();
		snap.init(STAFF);                 // start of the tick: staff equipped
		snap.onGameTick(MELEE);           // GameTick observes post-swap equipment (melee)
		// The projectile renders after this GameTick and must still resolve to the staff.
		assertEquals(STAFF, snap.launchWeapon());
	}

	@Test
	public void weaponSettlesToTheNewWeaponOnTheFollowingTick()
	{
		TickWeaponSnapshot snap = new TickWeaponSnapshot();
		snap.init(STAFF);
		snap.onGameTick(MELEE);           // swap tick
		snap.onGameTick(MELEE);           // next tick, swap has settled
		assertEquals(MELEE, snap.launchWeapon());
	}

	/** Equipping a weapon one tick, then attacking with it the next, attributes to the new weapon. */
	@Test
	public void swapThenAttackNextTickUsesTheNewWeapon()
	{
		TickWeaponSnapshot snap = new TickWeaponSnapshot();
		snap.init(STAFF);
		snap.onGameTick(MELEE);           // tick N: equipped melee (no shot fired)
		snap.onGameTick(MELEE);           // tick N+1: fire with melee
		assertEquals(MELEE, snap.launchWeapon());
	}

	@Test
	public void resetClearsBothSnapshots()
	{
		TickWeaponSnapshot snap = new TickWeaponSnapshot();
		snap.init(STAFF);
		snap.onGameTick(STAFF);
		snap.reset();
		assertEquals(NONE, snap.launchWeapon());
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class TriggerEvaluatorTest
{
	private static final Set<Triggers> NO_COVER = EnumSet.noneOf(Triggers.class);

	private static TriggerGroup group(Triggers... triggers)
	{
		Set<Triggers> set = triggers.length == 0
			? EnumSet.noneOf(Triggers.class)
			: EnumSet.copyOf(Arrays.asList(triggers));
		return new TriggerGroup(set, new ArrayList<>(), 100);
	}

	private static List<TriggerGroup> fire(
		List<TriggerGroup> groups, boolean wasSpec, boolean anyHit, boolean allZero,
		boolean allMax, boolean suppressMax, boolean suppressZero, boolean isKill,
		Set<Triggers> covered)
	{
		return TriggerEvaluator.selectFiringGroups(groups, wasSpec, anyHit, allZero,
			allMax, suppressMax, suppressZero, isKill, covered);
	}

	private static List<TriggerGroup> fire(
		List<TriggerGroup> groups, boolean wasSpec, boolean anyHit, boolean allZero,
		boolean allMax, boolean suppressMax, boolean suppressZero, boolean isKill,
		Set<Triggers> covered, int[] amounts)
	{
		return TriggerEvaluator.selectFiringGroups(groups, wasSpec, anyHit, allZero,
			allMax, suppressMax, suppressZero, isKill, covered, amounts);
	}

	// ---- matchesTrigger truth table ------------------------------------------------

	@Test
	public void regularHitMatchesOnlyNonSpecDamageThatIsNotAllMax()
	{
		// anyHit, not allMax, not spec -> match
		assertTrue(TriggerEvaluator.matchesTrigger(Triggers.REGULAR_HIT, false, true, false, false, false, false, false));
		// all max -> REGULAR_HIT must NOT fire (REGULAR_MAX owns that case)
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.REGULAR_HIT, false, true, false, true, false, false, false));
		// spec attack -> REGULAR_HIT must not fire
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.REGULAR_HIT, true, true, false, false, false, false, false));
		// no damage -> no match
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.REGULAR_HIT, false, false, true, false, false, false, false));
	}

	@Test
	public void regularZeroRespectsSuppressZero()
	{
		assertTrue(TriggerEvaluator.matchesTrigger(Triggers.REGULAR_ZERO, false, false, true, false, false, false, false));
		// suppressZero (e.g. thrall active) blocks it
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.REGULAR_ZERO, false, false, true, false, false, true, false));
		// spec zero is a different trigger
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.REGULAR_ZERO, true, false, true, false, false, false, false));
	}

	@Test
	public void maxTriggersRespectSuppressMax()
	{
		assertTrue(TriggerEvaluator.matchesTrigger(Triggers.REGULAR_MAX, false, true, false, true, false, false, false));
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.REGULAR_MAX, false, true, false, true, true, false, false));
		assertTrue(TriggerEvaluator.matchesTrigger(Triggers.SPECIAL_MAX, true, true, false, true, false, false, false));
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.SPECIAL_MAX, true, true, false, true, true, false, false));
	}

	@Test
	public void specialTriggersRequireWasSpec()
	{
		assertTrue(TriggerEvaluator.matchesTrigger(Triggers.SPECIAL_HIT, true, true, false, false, false, false, false));
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.SPECIAL_HIT, false, true, false, false, false, false, false));
		// all max -> SPECIAL_HIT must NOT fire (SPECIAL_MAX owns that case)
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.SPECIAL_HIT, true, true, false, true, false, false, false));
		assertTrue(TriggerEvaluator.matchesTrigger(Triggers.SPECIAL_ZERO, true, false, true, false, false, false, false));
		// SPECIAL_ZERO ignores suppressZero (only REGULAR_ZERO is gated by it)
		assertTrue(TriggerEvaluator.matchesTrigger(Triggers.SPECIAL_ZERO, true, false, true, false, false, true, false));
	}

	@Test
	public void allTriggerAlwaysMatchesAndKillNeedsKill()
	{
		assertTrue(TriggerEvaluator.matchesTrigger(Triggers.ALL, false, false, true, false, false, true, false));
		assertTrue(TriggerEvaluator.matchesTrigger(Triggers.KILL, false, false, false, false, false, false, true));
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.KILL, false, false, false, false, false, false, false));
	}

	@Test
	public void playerDeathNeverMatchesViaHitsplatPath()
	{
		assertFalse(TriggerEvaluator.matchesTrigger(Triggers.PLAYER_DEATH, false, true, false, false, false, false, true));
	}

	// ---- selectFiringGroups --------------------------------------------------------

	@Test
	public void emptyTriggerGroupsNeverFire()
	{
		List<TriggerGroup> groups = Collections.singletonList(group());
		assertTrue(fire(groups, false, true, false, false, false, false, false, NO_COVER).isEmpty());
	}

	@Test
	public void playerDeathGroupsAreSkippedOnHitsplatPath()
	{
		List<TriggerGroup> groups = Collections.singletonList(group(Triggers.PLAYER_DEATH));
		assertTrue(fire(groups, false, true, false, false, false, false, false, NO_COVER).isEmpty());
	}

	@Test
	public void regularHitFiresMatchingGroup()
	{
		TriggerGroup hit = group(Triggers.REGULAR_HIT);
		List<TriggerGroup> result = fire(Collections.singletonList(hit), false, true, false, false, false, false, false, NO_COVER);
		assertEquals(Collections.singletonList(hit), result);
	}

	@Test
	public void specAttackRoutesToSpecialGroupsNotRegular()
	{
		TriggerGroup regular = group(Triggers.REGULAR_HIT);
		TriggerGroup special = group(Triggers.SPECIAL_HIT);
		List<TriggerGroup> result = fire(Arrays.asList(regular, special), true, true, false, false, false, false, false, NO_COVER);
		assertEquals(Collections.singletonList(special), result);
	}

	@Test
	public void declarationOrderIsPreserved()
	{
		TriggerGroup a = group(Triggers.ALL);
		TriggerGroup b = group(Triggers.REGULAR_HIT);
		List<TriggerGroup> result = fire(Arrays.asList(a, b), false, true, false, false, false, false, false, NO_COVER);
		assertEquals(Arrays.asList(a, b), result);
	}

	@Test
	public void killGroupTakesExclusivePriorityOverNonKillGroups()
	{
		TriggerGroup kill = group(Triggers.KILL);
		TriggerGroup hit = group(Triggers.REGULAR_HIT);
		TriggerGroup all = group(Triggers.ALL);
		List<TriggerGroup> result = fire(Arrays.asList(hit, kill, all), false, true, false, false, false, false, true, NO_COVER);
		// On a kill with a KILL group present, only the kill group fires.
		assertEquals(Collections.singletonList(kill), result);
	}

	@Test
	public void nonKillGroupsFireWhenKillOccursButNoKillGroupExists()
	{
		TriggerGroup hit = group(Triggers.REGULAR_HIT);
		List<TriggerGroup> result = fire(Collections.singletonList(hit), false, true, false, false, false, false, true, NO_COVER);
		assertEquals(Collections.singletonList(hit), result);
	}

	@Test
	public void killGroupWithExtraTriggerActsAsAndGate()
	{
		// KILL + SPECIAL_MAX: fires only if the kill was also a special max hit.
		TriggerGroup killSpecMax = group(Triggers.KILL, Triggers.SPECIAL_MAX);

		List<TriggerGroup> noSpec = fire(Collections.singletonList(killSpecMax),
			false, true, false, true, false, false, true, NO_COVER);
		assertTrue("kill but not a spec max -> AND gate blocks", noSpec.isEmpty());

		List<TriggerGroup> specMax = fire(Collections.singletonList(killSpecMax),
			true, true, false, true, false, false, true, NO_COVER);
		assertEquals(Collections.singletonList(killSpecMax), specMax);
	}

	@Test
	public void killOnlyGroupFiresOnKillRegardlessOfDamage()
	{
		TriggerGroup kill = group(Triggers.KILL);
		List<TriggerGroup> result = fire(Collections.singletonList(kill), false, false, true, false, false, false, true, NO_COVER);
		assertEquals(Collections.singletonList(kill), result);
	}

	@Test
	public void weaponCoveredTriggersFilterOverlappingGlobalGroups()
	{
		TriggerGroup overlapping = group(Triggers.REGULAR_HIT); // already handled by weapon
		TriggerGroup distinct = group(Triggers.REGULAR_ZERO);
		Set<Triggers> covered = EnumSet.of(Triggers.REGULAR_HIT);

		// regular hit outcome: the overlapping global group is filtered out, distinct doesn't match -> nothing
		List<TriggerGroup> onHit = fire(Arrays.asList(overlapping, distinct), false, true, false, false, false, false, false, covered);
		assertTrue(onHit.isEmpty());

		// zero outcome: distinct (REGULAR_ZERO) survives the filter and matches
		List<TriggerGroup> onZero = fire(Arrays.asList(overlapping, distinct), false, false, true, false, false, false, false, covered);
		assertEquals(Collections.singletonList(distinct), onZero);
	}

	@Test
	public void weaponCoveredDoesNotFilterEmptyTriggerlessGroups()
	{
		// An "ALL" global group has triggers; covered set should not remove it since ALL isn't covered.
		TriggerGroup all = group(Triggers.ALL);
		Set<Triggers> covered = EnumSet.of(Triggers.REGULAR_HIT);
		List<TriggerGroup> result = fire(Collections.singletonList(all), false, true, false, false, false, false, false, covered);
		assertEquals(Collections.singletonList(all), result);
	}

	// ---- amount triggers -----------------------------------------------------------

	@Test
	public void matchesAmountTriggerComparesSummedHitsplatsAgainstCondition()
	{
		AmountCondition eq73 = new AmountCondition(AmountCondition.Op.EQUAL, 73);
		// a multi-hit regular attack whose hitsplats sum to 73 matches
		assertTrue(TriggerEvaluator.matchesAmountTrigger(Triggers.REGULAR_AMOUNT, eq73, false, new int[]{70, 3}));
		// an individual hitsplat of 73 but a total of 83 does NOT match (accumulated, not per-splat)
		assertFalse(TriggerEvaluator.matchesAmountTrigger(Triggers.REGULAR_AMOUNT, eq73, false, new int[]{10, 73}));
		// total short of 73 -> no match
		assertFalse(TriggerEvaluator.matchesAmountTrigger(Triggers.REGULAR_AMOUNT, eq73, false, new int[]{10, 20}));
		// spec attack -> REGULAR_AMOUNT (a non-special trigger) must not fire
		assertFalse(TriggerEvaluator.matchesAmountTrigger(Triggers.REGULAR_AMOUNT, eq73, true, new int[]{73}));
		// no condition, or no hitsplats -> never fires
		assertFalse(TriggerEvaluator.matchesAmountTrigger(Triggers.REGULAR_AMOUNT, null, false, new int[]{73}));
		assertFalse(TriggerEvaluator.matchesAmountTrigger(Triggers.REGULAR_AMOUNT, eq73, false, new int[0]));
	}

	@Test
	public void amountTriggerAccumulatesMultipleHitsplats()
	{
		// A GREATER:40 condition fires when four splats (18+12+9+6 = 45) exceed 40, even though no single
		// splat does.
		AmountCondition gt40 = new AmountCondition(AmountCondition.Op.GREATER, 40);
		assertTrue(TriggerEvaluator.matchesAmountTrigger(Triggers.REGULAR_AMOUNT, gt40, false, new int[]{18, 12, 9, 6}));
		assertFalse(TriggerEvaluator.matchesAmountTrigger(Triggers.REGULAR_AMOUNT, gt40, false, new int[]{18, 12, 9}));
	}

	@Test
	public void specialAmountTriggerRequiresSpecAttack()
	{
		AmountCondition eq50 = new AmountCondition(AmountCondition.Op.EQUAL, 50);
		// a spec attack landing a 50 matches SPECIAL_AMOUNT
		assertTrue(TriggerEvaluator.matchesAmountTrigger(Triggers.SPECIAL_AMOUNT, eq50, true, new int[]{50}));
		// same damage on a regular attack must not fire SPECIAL_AMOUNT
		assertFalse(TriggerEvaluator.matchesAmountTrigger(Triggers.SPECIAL_AMOUNT, eq50, false, new int[]{50}));
		// spec attack but wrong damage -> no match
		assertFalse(TriggerEvaluator.matchesAmountTrigger(Triggers.SPECIAL_AMOUNT, eq50, true, new int[]{49}));
	}

	@Test
	public void specialAmountGroupFiresOnlyOnMatchingSpecAttack()
	{
		TriggerGroup amount = group(Triggers.SPECIAL_AMOUNT);
		amount.setAmountCondition(Triggers.SPECIAL_AMOUNT, new AmountCondition(AmountCondition.Op.GREATER, 40));

		// spec attack totalling 45 -> fires
		List<TriggerGroup> onSpec = fire(Collections.singletonList(amount), true, true, false, false, false, false, false, NO_COVER, new int[]{45});
		assertEquals(Collections.singletonList(amount), onSpec);

		// same total on a regular attack -> does not fire
		List<TriggerGroup> onRegular = fire(Collections.singletonList(amount), false, true, false, false, false, false, false, NO_COVER, new int[]{45});
		assertTrue(onRegular.isEmpty());
	}

	@Test
	public void amountTriggerGroupFiresOnlyWhenDamageMatches()
	{
		TriggerGroup amount = group(Triggers.REGULAR_AMOUNT);
		amount.setAmountCondition(Triggers.REGULAR_AMOUNT, new AmountCondition(AmountCondition.Op.EQUAL, 73));

		// total of 73 on a regular attack -> fires
		List<TriggerGroup> onMatch = fire(Collections.singletonList(amount), false, true, false, false, false, false, false, NO_COVER, new int[]{73});
		assertEquals(Collections.singletonList(amount), onMatch);

		// total of 50 -> does not fire
		List<TriggerGroup> noMatch = fire(Collections.singletonList(amount), false, true, false, false, false, false, false, NO_COVER, new int[]{50});
		assertTrue(noMatch.isEmpty());
	}

	@Test
	public void amountTriggerGroupHonoursWeaponCoveredTriggers()
	{
		TriggerGroup amount = group(Triggers.REGULAR_AMOUNT);
		amount.setAmountCondition(Triggers.REGULAR_AMOUNT, new AmountCondition(AmountCondition.Op.EQUAL, 73));
		Set<Triggers> covered = EnumSet.of(Triggers.REGULAR_AMOUNT);
		// the weapon already handles REGULAR_AMOUNT, so an overlapping global group is skipped
		assertTrue(fire(Collections.singletonList(amount), false, true, false, false, false, false, false, covered, new int[]{73}).isEmpty());
	}

	@Test
	public void amountTriggerWithKillActsAsAndGate()
	{
		TriggerGroup killAmount = group(Triggers.KILL, Triggers.SPECIAL_AMOUNT);
		killAmount.setAmountCondition(Triggers.SPECIAL_AMOUNT, new AmountCondition(AmountCondition.Op.GREATER, 40));

		// spec total over 40 but no kill -> KILL gate blocks it
		assertTrue(fire(Collections.singletonList(killAmount), true, true, false, false, false, false, false, NO_COVER, new int[]{45}).isEmpty());
		// same, but on a kill -> fires
		assertEquals(Collections.singletonList(killAmount),
			fire(Collections.singletonList(killAmount), true, true, false, false, false, false, true, NO_COVER, new int[]{45}));
	}

	@Test
	public void suppressMaxBlocksMaxGroupsButLeavesHitGroups()
	{
		TriggerGroup max = group(Triggers.REGULAR_MAX);
		// all-max small hit gets suppressed
		assertTrue(fire(Collections.singletonList(max), false, true, false, true, true, false, false, NO_COVER).isEmpty());
		// without suppression it fires
		assertEquals(Collections.singletonList(max),
			fire(Collections.singletonList(max), false, true, false, true, false, false, false, NO_COVER));
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class TriggerGroupTest
{
	@Test
	public void serializeDeserializeRoundTrips()
	{
		Set<Triggers> original = EnumSet.of(Triggers.REGULAR_HIT, Triggers.KILL, Triggers.SPECIAL_MAX);
		String serialized = TriggerGroup.serializeTriggers(original);
		assertEquals(original, TriggerGroup.deserializeTriggers(serialized));
	}

	@Test
	public void emptySetSerializesToEmptyString()
	{
		assertEquals("", TriggerGroup.serializeTriggers(EnumSet.noneOf(Triggers.class)));
		assertEquals("", TriggerGroup.serializeTriggers(null));
	}

	@Test
	public void deserializeHandlesNullBlankAndWhitespace()
	{
		assertTrue(TriggerGroup.deserializeTriggers(null).isEmpty());
		assertTrue(TriggerGroup.deserializeTriggers("").isEmpty());
		assertTrue(TriggerGroup.deserializeTriggers("   ").isEmpty());
		// surrounding whitespace and empty entries are tolerated
		assertEquals(EnumSet.of(Triggers.ALL),
			TriggerGroup.deserializeTriggers(" ALL ,, "));
	}

	@Test
	public void deserializeIgnoresUnknownTokensButKeepsValidOnes()
	{
		// Forward/backward compat: an unknown trigger name (e.g. removed enum value) must not
		// blow away the rest of a user's saved group.
		Set<Triggers> result = TriggerGroup.deserializeTriggers("REGULAR_HIT,SOMETHING_REMOVED,KILL");
		assertEquals(EnumSet.of(Triggers.REGULAR_HIT, Triggers.KILL), result);
	}

	@Test
	public void amountConditionsSerializeDeserializeRoundTrip()
	{
		Map<Triggers, AmountCondition> original = new EnumMap<>(Triggers.class);
		original.put(Triggers.REGULAR_AMOUNT, new AmountCondition(AmountCondition.Op.EQUAL, 73));

		String serialized = TriggerGroup.serializeAmountConditions(original);
		Map<Triggers, AmountCondition> restored = TriggerGroup.deserializeAmountConditions(serialized);

		assertEquals(1, restored.size());
		AmountCondition c = restored.get(Triggers.REGULAR_AMOUNT);
		assertEquals(AmountCondition.Op.EQUAL, c.getOp());
		assertEquals(73, c.getValue());
	}

	@Test
	public void emptyAmountConditionsSerializeToEmptyString()
	{
		assertEquals("", TriggerGroup.serializeAmountConditions(new EnumMap<>(Triggers.class)));
		assertEquals("", TriggerGroup.serializeAmountConditions(null));
		assertTrue(TriggerGroup.deserializeAmountConditions(null).isEmpty());
		assertTrue(TriggerGroup.deserializeAmountConditions("").isEmpty());
		assertTrue(TriggerGroup.deserializeAmountConditions("  ").isEmpty());
	}

	@Test
	public void deserializeAmountConditionsIgnoresMalformedEntries()
	{
		// A valid entry survives alongside an unknown trigger and a malformed condition.
		Map<Triggers, AmountCondition> restored = TriggerGroup.deserializeAmountConditions(
			"REGULAR_AMOUNT=GREATER:50;BOGUS=EQUAL:1;REGULAR_MAX=notacondition");
		assertEquals(1, restored.size());
		assertEquals(AmountCondition.Op.GREATER, restored.get(Triggers.REGULAR_AMOUNT).getOp());
		assertEquals(50, restored.get(Triggers.REGULAR_AMOUNT).getValue());
	}

	@Test
	public void newTriggerGroupHasNoAmountConditions()
	{
		TriggerGroup g = new TriggerGroup(null, null, 100);
		assertTrue(g.getAmountConditions().isEmpty());
		assertNull(g.getAmountCondition(Triggers.REGULAR_AMOUNT));
		g.setAmountCondition(Triggers.REGULAR_AMOUNT, new AmountCondition(AmountCondition.Op.EQUAL, 5));
		assertEquals(5, g.getAmountCondition(Triggers.REGULAR_AMOUNT).getValue());
		// A null condition clears it.
		g.setAmountCondition(Triggers.REGULAR_AMOUNT, null);
		assertNull(g.getAmountCondition(Triggers.REGULAR_AMOUNT));
	}

	@Test
	public void constructorDefaultsNullArgsToEmptyCollections()
	{
		TriggerGroup g = new TriggerGroup(null, null, 50);
		assertTrue(g.getTriggers().isEmpty());
		assertTrue(g.getSounds().isEmpty());
		assertEquals(50, g.getChance());
	}

	private static TriggerGroup named(String name)
	{
		TriggerGroup g = new TriggerGroup(null, null, 100);
		g.setName(name);
		return g;
	}

	@Test
	public void isNameTakenIsCaseInsensitiveAndSkipsExcludedGroup()
	{
		TriggerGroup a = named("Crush");
		TriggerGroup b = named("Slash");
		List<TriggerGroup> groups = new ArrayList<>();
		groups.add(a);
		groups.add(b);

		assertTrue(TriggerGroup.isNameTaken(groups, "crush", null));
		assertFalse(TriggerGroup.isNameTaken(groups, "Stab", null));
		// renaming 'a' to its own (differently-cased) name must not count as a clash with itself
		assertFalse(TriggerGroup.isNameTaken(groups, "CRUSH", a));
		// but it still clashes with the *other* group
		assertTrue(TriggerGroup.isNameTaken(groups, "slash", a));
	}

	@Test
	public void defaultNameSkipsUsedNumbers()
	{
		List<TriggerGroup> groups = new ArrayList<>();
		assertEquals("Sound Group 1", TriggerGroup.defaultName(groups));

		groups.add(named("Sound Group 1"));
		groups.add(named("Sound Group 3"));
		// 1 is taken, 2 is free
		assertEquals("Sound Group 2", TriggerGroup.defaultName(groups));

		groups.add(named("Sound Group 2"));
		// 1,2,3 taken -> 4
		assertEquals("Sound Group 4", TriggerGroup.defaultName(groups));
	}
}

package com.customweaponsfx;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Covers the weapon CRUD lifecycle: add / change (re-point) / copy / remove, keeping the in-memory
 * list and the config store in sync, firing the rebuild callback, and raising a conflict (instead of
 * clobbering) when a target id is already configured.
 */
public class WeaponManagerTest
{
	private static final int DRAGON_DAGGER = 1215;
	private static final int ABYSSAL_WHIP = 4151;
	private static final int ARMADYL_GODSWORD = 11802;

	/** In-memory backend mirroring ConfigManager's string-only persistence. */
	private static final class MapBackend implements CustomWeaponSfxConfigStore.Backend
	{
		final Map<String, String> map = new HashMap<>();

		@Override public String get(String key) { return map.get(key); }
		@Override public void set(String key, Object value) { map.put(key, String.valueOf(value)); }
		@Override public void unset(String key) { map.remove(key); }
	}

	private CustomWeaponSfxConfigStore store;
	private WeaponManager manager;
	private int changedCount;
	private String lastConflict;

	@Before
	public void setUp()
	{
		store = new CustomWeaponSfxConfigStore(new MapBackend());
		changedCount = 0;
		lastConflict = null;
		manager = new WeaponManager(store, () -> changedCount++, msg -> lastConflict = msg);
	}

	private static TriggerGroup group()
	{
		List<SoundEntry> sounds = new ArrayList<>();
		sounds.add(new SoundEntry("bundled:bonk", 75, 1.0));
		return new TriggerGroup(EnumSet.of(Triggers.REGULAR_HIT), sounds, 100);
	}

	// ---- add -----------------------------------------------------------------------------------

	@Test
	public void addCreatesEntryPersistsAndNotifies()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");

		WeaponEntry entry = manager.find(DRAGON_DAGGER);
		assertNotNull(entry);
		assertEquals("Dragon dagger", entry.getWeaponName());
		assertTrue("new weapons start enabled", entry.isEnabled());
		assertEquals(1, changedCount);

		// Persisted: a reload from the same store finds it.
		assertEquals(1, store.loadWeapons().size());
	}

	@Test
	public void addingADuplicateIdIsANoOp()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		manager.add(DRAGON_DAGGER, "Dragon dagger (again)");

		assertEquals(1, manager.snapshot().size());
		assertEquals("Dragon dagger", manager.find(DRAGON_DAGGER).getWeaponName());
		assertEquals("second add did not fire onChanged", 1, changedCount);
	}

	// ---- load / snapshot -----------------------------------------------------------------------

	@Test
	public void loadReplacesInMemoryListFromStore()
	{
		WeaponEntry persisted = new WeaponEntry(ABYSSAL_WHIP, "Abyssal whip", new ArrayList<>());
		store.saveWeapon(persisted);
		store.saveWeaponIds(java.util.Collections.singletonList(persisted));

		manager.load();
		assertEquals(1, manager.snapshot().size());
		assertNotNull(manager.find(ABYSSAL_WHIP));
	}

	@Test
	public void snapshotIsADefensiveCopy()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		List<WeaponEntry> snap = manager.snapshot();
		snap.clear();
		assertEquals("mutating the snapshot must not affect the manager", 1, manager.snapshot().size());
	}

	// ---- change (re-point) ---------------------------------------------------------------------

	@Test
	public void changeRepointsPreservingGroupsAndEnabledState()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		WeaponEntry original = manager.find(DRAGON_DAGGER);
		original.getGroups().add(group());
		original.setEnabled(false);
		List<TriggerGroup> groupsRef = original.getGroups();

		changedCount = 0;
		manager.change(DRAGON_DAGGER, ARMADYL_GODSWORD, "Armadyl godsword");

		assertNull("old id is gone", manager.find(DRAGON_DAGGER));
		WeaponEntry moved = manager.find(ARMADYL_GODSWORD);
		assertNotNull(moved);
		assertEquals("Armadyl godsword", moved.getWeaponName());
		assertFalse("enabled state carried over", moved.isEnabled());
		assertSame("sound groups carried over", groupsRef, moved.getGroups());
		assertEquals(1, changedCount);

		// Persistence reflects the move.
		List<WeaponEntry> reloaded = store.loadWeapons();
		assertEquals(1, reloaded.size());
		assertEquals(ARMADYL_GODSWORD, reloaded.get(0).getItemId());
	}

	@Test
	public void changeToSameIdIsANoOp()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		changedCount = 0;
		manager.change(DRAGON_DAGGER, DRAGON_DAGGER, "Dragon dagger");
		assertEquals(0, changedCount);
		assertNotNull(manager.find(DRAGON_DAGGER));
	}

	@Test
	public void changeOfAMissingWeaponIsANoOp()
	{
		manager.change(DRAGON_DAGGER, ARMADYL_GODSWORD, "Armadyl godsword");
		assertEquals(0, changedCount);
		assertNull(manager.find(ARMADYL_GODSWORD));
	}

	@Test
	public void changeOntoAnAlreadyConfiguredIdConflictsAndAborts()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		manager.add(ARMADYL_GODSWORD, "Armadyl godsword");
		changedCount = 0;

		manager.change(DRAGON_DAGGER, ARMADYL_GODSWORD, "Armadyl godsword");

		assertNotNull("conflict raised", lastConflict);
		assertEquals("both weapons left intact", 2, manager.snapshot().size());
		assertNotNull(manager.find(DRAGON_DAGGER));
		assertEquals(0, changedCount);
	}

	// ---- copy ----------------------------------------------------------------------------------

	@Test
	public void copyDeepCopiesGroupsAndEnabledState()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		WeaponEntry source = manager.find(DRAGON_DAGGER);
		source.getGroups().add(group());
		source.setEnabled(false);
		changedCount = 0;

		manager.copy(DRAGON_DAGGER, ARMADYL_GODSWORD, "Armadyl godsword");

		WeaponEntry copy = manager.find(ARMADYL_GODSWORD);
		assertNotNull(copy);
		assertFalse("enabled state copied", copy.isEnabled());
		assertEquals(1, copy.getGroups().size());
		assertEquals("source kept too", 2, manager.snapshot().size());
		assertEquals(1, changedCount);

		// Deep copy: the two weapons share no mutable group/sound state.
		assertNotSame(source.getGroups(), copy.getGroups());
		assertNotSame(source.getGroups().get(0), copy.getGroups().get(0));
		assertNotSame(source.getGroups().get(0).getSounds().get(0),
			copy.getGroups().get(0).getSounds().get(0));
	}

	@Test
	public void copyFromAMissingSourceIsANoOp()
	{
		manager.copy(DRAGON_DAGGER, ARMADYL_GODSWORD, "Armadyl godsword");
		assertEquals(0, changedCount);
		assertNull(manager.find(ARMADYL_GODSWORD));
	}

	@Test
	public void copyOntoAnAlreadyConfiguredIdConflictsAndAborts()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		manager.add(ARMADYL_GODSWORD, "Armadyl godsword");
		changedCount = 0;

		manager.copy(DRAGON_DAGGER, ARMADYL_GODSWORD, "Armadyl godsword");

		assertNotNull(lastConflict);
		assertEquals(2, manager.snapshot().size());
		assertEquals(0, changedCount);
	}

	// ---- remove --------------------------------------------------------------------------------

	@Test
	public void removeDeletesEntryFromMemoryAndStore()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		manager.add(ABYSSAL_WHIP, "Abyssal whip");
		changedCount = 0;

		manager.remove(DRAGON_DAGGER);

		assertNull(manager.find(DRAGON_DAGGER));
		assertNotNull("other weapon untouched", manager.find(ABYSSAL_WHIP));
		assertEquals(1, changedCount);

		List<WeaponEntry> reloaded = store.loadWeapons();
		assertEquals(1, reloaded.size());
		assertEquals(ABYSSAL_WHIP, reloaded.get(0).getItemId());
	}

	@Test
	public void removingAnUnknownIdStillRewritesTheIndexAndNotifies()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		changedCount = 0;
		manager.remove(ARMADYL_GODSWORD);
		// Nothing was configured under that id; the surviving weapon is unaffected.
		assertNotNull(manager.find(DRAGON_DAGGER));
		assertEquals(1, manager.snapshot().size());
	}

	@Test
	public void clearEmptiesTheInMemoryList()
	{
		manager.add(DRAGON_DAGGER, "Dragon dagger");
		manager.clear();
		assertTrue(manager.snapshot().isEmpty());
	}
}

package com.customweaponsfx;

import java.util.HashMap;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Covers which default in-game sound-effect ids the plugin silences: the user's configured id list,
 * including parsing of messy input and persistence through the config store.
 */
public class WeaponSoundMuteFilterTest
{
	/** In-memory backend mirroring ConfigManager's string-only persistence. */
	private static final class MapBackend implements CustomWeaponSfxConfigStore.Backend
	{
		final Map<String, String> map = new HashMap<>();

		@Override public String get(String key) { return map.get(key); }
		@Override public void set(String key, Object value) { map.put(key, String.valueOf(value)); }
		@Override public void unset(String key) { map.remove(key); }
	}

	private CustomWeaponSfxConfigStore store;
	private WeaponSoundMuteFilter filter;

	@Before
	public void setUp()
	{
		store = new CustomWeaponSfxConfigStore(new MapBackend());
		filter = new WeaponSoundMuteFilter(store);
	}

	@Test
	public void nothingIsMutedWithoutAnyConfig()
	{
		assertFalse(filter.isMuted(2554));
	}

	@Test
	public void userConfiguredIdsAreMuted()
	{
		filter.setIds("2554, 2555");
		assertTrue(filter.isMuted(2554));
		assertTrue(filter.isMuted(2555));
		assertFalse(filter.isMuted(2556));
	}

	@Test
	public void blankAndInvalidTokensAreIgnored()
	{
		filter.setIds(" 2554 ,, abc, 2555,");
		assertTrue(filter.isMuted(2554));
		assertTrue(filter.isMuted(2555));
		assertFalse(filter.isMuted(0));
	}

	@Test
	public void setIdsPersistsThroughTheStore()
	{
		filter.setIds("12345");
		assertTrue(store.getMutedWeaponSoundIdsRaw().contains("12345"));

		// A fresh filter loading from the same store sees the persisted mute.
		WeaponSoundMuteFilter reloaded = new WeaponSoundMuteFilter(store);
		reloaded.load();
		assertTrue(reloaded.isMuted(12345));
	}

	@Test
	public void clearDropsUserMutes()
	{
		filter.setIds("2554");
		filter.clear();
		assertFalse(filter.isMuted(2554));
	}
}
